window.QF_SITES = [{"id":"chengdu-wuhouci","name":"成都武侯祠廉洁文化基地","city":"成都市","district":"武侯区","address":"武侯祠大街231号","lat":30.6457,"lng":104.0495,"verify":"verified","categories":["清官廉吏","家风家训"],"tags":["三国文化","诸葛亮","省级廉洁文化基地","君臣合祀"],"year":2018,"summary":"全国唯一君臣合祀祠庙，也是四川首批省级廉洁文化基地。基地以诸葛亮\"鞠躬尽瘁、死而后已\"的一生为主线，梳理《诫子书》《出师表》中的清廉、勤政、齐家思想。","highlights":["\"淡泊明志、宁静致远\"主题展线","《诫子书》家风家训专题","诸葛亮勤政廉政史迹陈列"],"story":"诸葛亮主政蜀汉二十余年，身后\"内无余帛，外无赢财\"，家中唯有桑树八百株、薄田十五顷。他以《诫子书》教子\"静以修身，俭以养德\"，把个人操守与家国责任绑在一起。武侯祠廉洁文化基地把这份\"公烛无私光\"的品格，转化为党员干部可感可学的历史镜鉴。","quote":"非淡泊无以明志，非宁静无以致远。","phone":"028-85567778","official":true},{"id":"chengdu-shenguan","name":"升庵桂湖暨杨氏宗祠","city":"成都市","district":"新都区","address":"桂湖街道桂湖中路附109号","lat":30.8246,"lng":104.1596,"verify":"verified","categories":["清官廉吏","家风家训"],"tags":["杨升庵","明代状元","杨氏家风","省级廉洁文化基地"],"year":2018,"summary":"明代状元杨升庵（杨慎）故居与杨氏宗祠所在，四川首批省级廉洁文化基地。杨氏一门\"四世为官、清廉传家\"，基地以家谱、家训、家书呈现\"临利不敢先人，见义不敢后身\"的家风。","highlights":["杨氏\"清白传家\"家训碑刻","杨升庵谪戍云南仍著述不辍的治学精神","桂湖园林中的廉洁楹联"],"story":"杨升庵因\"大礼议\"触怒嘉靖帝，被杖责后谪戍云南三十余年。身处逆境，他不改清节，讲学著书、教化边民，留下四百余种著述。杨氏家风讲\"以德立身、以廉守家\"，其家族世代为官而无一人以贪墨败名，成为四川家风家训教育的经典样本。","quote":"临利不敢先人，见义不敢后身。","phone":"028-83972518","official":true},{"id":"chengdu-tianfu-jiafeng-guan","name":"天府家风馆","city":"成都市","district":"新都区","address":"斑竹园街道升庵村","lat":30.859,"lng":104.121,"verify":"verified","categories":["家风家训","廉政教育"],"tags":["省级家风馆","川渝好家风环线","先贤家风","红色家风"],"year":2019,"summary":"四川省重点打造的家风教育主阵地，也是\"川渝好家风\"廉洁文化体验环线的核心枢纽。馆内以\"先贤家风、红色家风、当代家教、时代新家\"四大篇章，系统展示巴蜀家风文化谱系。","highlights":["先贤家风馆：李密、三苏、杨升庵家风长卷","红色家风馆：老一辈革命家家书手迹","当代家教与时代新家互动展区"],"story":"家风馆把\"家\"作为廉洁教育的最小单元：从《陈情表》的孝，到三苏\"读书正业、慈孝仁爱\"的训，再到革命先辈\"不搞特殊化\"的家书，串起一条\"修身—齐家—报国\"的链条。参观者在这里常被问同一个问题：留给子女最值钱的东西是什么？","quote":"积善之家，必有余庆。","phone":"028-86329999","official":true},{"id":"chengdu-shuxiang-qingyun","name":"\"蔬乡清韵\"优秀传统文化教育基地","city":"成都市","district":"彭州市","address":"濛阳街道蔬香南路","lat":30.956,"lng":104.113,"verify":"verified","categories":["清官廉吏","家风家训"],"tags":["省级廉洁文化基地","耕读文化","菜蔬之乡","乡贤清风"],"year":2018,"summary":"依托彭州\"蔬菜之乡\"的耕读传统建设，是四川首批省级廉洁文化基地中唯一以农耕文明与乡土家风为主题的基地，把\"勤耕\"与\"清廉\"连成一脉。","highlights":["农耕器具与家风故事对照展陈","彭州历代乡贤廉吏谱","田间地头的家风课堂"],"story":"基地以\"菜根香、布衣暖\"的朴素生活为底色，讲当地人\"一畦菜、一担粮，来路要干净\"的口头规矩。耕读传家不只是一句老话，它把劳动、节制与诚信写进日常，是廉洁文化最接地气的形态。","quote":"咬得菜根，百事可做。","phone":"18382083755","official":true},{"id":"chengdu-kejia-jiafeng-guan","name":"四川客家家风馆","city":"成都市","district":"龙泉驿区","address":"洛带镇三峨街999号博客土楼三楼","lat":30.637,"lng":104.323,"verify":"verified","categories":["家风家训"],"tags":["客家文化","族规家训","移民家风","川渝好家风环线"],"year":2018,"summary":"位于\"中国西部客家第一镇\"洛带古镇，馆内以客家族谱、族规、楹联为线索，展示客家移民\"勤俭持家、清白做人\"的家风传承。","highlights":["客家族规家训典籍展","土楼家训楹联长廊","客家\"耕读传家\"生活场景复原"],"story":"客家人迁徙千里，随身带的不是金银，而是族谱与祖训。\"宁卖祖宗田，不忘祖宗言\"——族规里写满了勤俭、读书、戒贪的条条框框。家风馆让今天的参观者看到：一个家族能走多远，往往取决于它守住什么。","quote":"宁卖祖宗田，不忘祖宗言。","phone":"028-84893693","official":false},{"id":"chengdu-wufengxi-jiafeng-xueyuan","name":"金堂县五凤溪家风文化学院","city":"成都市","district":"金堂县","address":"五凤镇金箱村二组","lat":30.735,"lng":104.508,"verify":"verified","categories":["家风家训","廉政教育"],"tags":["贺氏家训","古镇家风","现场教学","川渝好家风环线"],"year":2018,"summary":"以五凤溪古镇贺氏等家族家风资源为载体建成的家风文化学院，开设家风讲堂与现场教学课程，是成都东部重要的廉洁教育现场教学点。","highlights":["贺氏\"耕读传家\"家训碑","古镇移民家风研学线路","家风讲堂现场教学"],"story":"五凤溪曾是沱江边的水陆码头，商贾云集。贺氏家族在此立下\"不义之财不入家门\"的规矩，家业越大，家训越严。学院把古镇的院落、码头、碑刻变成课堂，让家风教育从纸面走进现场。","quote":"不义而富且贵，于我如浮云。","phone":"18780207189","official":false},{"id":"zigong-wuyuzhang-guju","name":"吴玉章故居","city":"自贡市","district":"荣县","address":"双石镇蔡家堰村6组","lat":29.3984,"lng":104.3768,"verify":"verified","categories":["红色廉洁","家风家训"],"tags":["延安五老","省级廉洁文化基地","革命教育家","川渝好家风环线"],"year":2018,"summary":"无产阶级革命家、教育家吴玉章同志的故居，四川首批省级廉洁文化基地。故居陈列其一生的革命与办学经历，尤以\"一辈子做好事\"的自律品格为教育主线。","highlights":["吴玉章生平事迹陈列","\"一辈子做好事\"廉洁自述","家风家训与家书展"],"story":"吴玉章自青年投身革命，至新中国成立后任中国人民大学校长，始终拒绝特殊待遇，把稿费与积蓄捐作办学基金。他说自己一生只求\"做些有益于人民的事\"。故居里那张旧木桌，是他几十年伏案的地方，也是\"公私分明\"四个字最直观的注解。","quote":"人生在世，事业为重；一息尚存，绝不松劲。","phone":"0813-6919293","official":true},{"id":"zigong-jiangjie-guli","name":"江姐故里红色教育基地","city":"自贡市","district":"大安区","address":"大山铺镇江姐村（江家湾）","lat":29.3935,"lng":104.8495,"verify":"verified","categories":["红色廉洁","廉政教育"],"tags":["江竹筠","红岩精神","烈士故居","川渝好家风环线"],"year":2021,"summary":"革命烈士江竹筠（江姐）故里，由江姐故居、江姐生平事迹陈列馆与红色教育园区组成。基地以\"狱中八条\"与《托孤信》为核心素材，讲信仰与纪律。","highlights":["江姐生平事迹陈列馆","《托孤信》手迹与家风故事","\"狱中八条\"警示教育展墙"],"story":"江竹筠在渣滓洞受尽酷刑而始终未吐一字。牺牲前她写下托孤信，叮嘱孩子\"以建设新中国为志\"。与她同时期的狱中同志留下\"狱中八条\"，第一条便是\"防止领导成员腐化\"。血的教训写成的纪律条文，至今读来仍有分量。","quote":"竹签子是竹子做的，共产党员的意志是钢铁。","phone":"0813-5888820","official":false},{"id":"panzhihua-sanxian-bwg","name":"攀枝花中国三线建设博物馆","city":"攀枝花市","district":"仁和区","address":"仁和镇干坝塘","lat":26.523,"lng":101.729,"verify":"verified","categories":["行业清风","红色廉洁"],"tags":["三线建设","省级廉洁文化基地","艰苦奋斗","工业遗产"],"year":2015,"summary":"全国唯一以三线建设为主题的国家级博物馆，四川首批省级廉洁文化基地。馆藏十万余件文物，再现\"好人好马上三线\"的艰苦创业史与建设者清苦自守的作风。","highlights":["三线建设决策与建设历程展","\"不想爹不想妈，不出铁不回家\"建设者群像","三线建设者廉洁自律实物档案"],"story":"上世纪六十年代，数十万建设者从大城市走进攀西裂谷，住席棚、喝泥水，用肩挑背扛建起钢铁基地。物资紧缺年代，工地上\"一个螺丝钉都登记入账\"。他们留下的不只是工厂，更是一种\"公家的东西一分不沾\"的自觉。","quote":"献了青春献终身，献了终身献子孙。","phone":null,"official":true},{"id":"luzhou-sidu-chishui","name":"红军长征四渡赤水纪念地","city":"泸州市","district":"古蔺县","address":"太平镇（太平渡）、二郎镇（二郎滩）","lat":28.1903,"lng":105.9578,"verify":"verified","categories":["红色廉洁"],"tags":["长征","省级廉洁文化基地","四渡赤水","太平渡陈列馆"],"year":2018,"summary":"红军长征四渡赤水在古蔺留下的核心纪念地群，含太平渡陈列馆、二郎滩渡口、红军街旧址等，是四川首批省级廉洁文化基地之一。","highlights":["太平渡陈列馆与红军渡口","红军街纪律遗迹（\"不拿群众一针一线\"）","长征中的群众纪律故事展"],"story":"红军在古蔺三进三出，群众却\"见了红军如见亲人\"。原因写在纪律里：借门板要还、吃粮要付钱、宿营不扰民。太平渡的老街上，还留着红军写下的标语与赊账条。四渡赤水的胜利，一半靠谋略，一半靠纪律赢得的人心。","quote":"加强纪律性，革命无不胜。","phone":"0830-7400170","official":true},{"id":"luzhou-huguo-zhanzheng","name":"护国战争纪念馆","city":"泸州市","district":"纳溪区","address":"永宁街道五顶社区棉花坡路4号（陶家大院）","lat":28.7681,"lng":105.3722,"verify":"verified","categories":["红色廉洁"],"tags":["护国战争","朱德","棉花坡战役","爱国主义教育"],"year":2018,"summary":"依托护国战争棉花坡战役遗址建设，展示朱德同志在纳溪率部作战、以少胜多的战例，是泸州重要的爱国主义与革命传统教育基地。","highlights":["棉花坡战役战史陈列","朱德在泸州时期的治军与爱民事迹","战壕遗址现场教学"],"story":"1916 年，朱德率部在棉花坡与北洋军苦战月余。他身先士卒、与士兵同食同宿，被称作\"朱旅长\"。多年后他回忆这段经历，说自己真正懂得\"兵民是胜利之本\"。一个将领的廉洁与担当，往往先体现在与士兵同甘共苦上。","quote":"与士卒同甘苦，则士卒乐为之用。","phone":null,"official":false},{"id":"deyang-mianzhu-nianhua","name":"绵竹廉洁年画创作基地","city":"德阳市","district":"绵竹市","address":"孝德镇年画村","lat":31.13,"lng":104.213,"verify":"verified","categories":["家风家训","廉政教育"],"tags":["绵竹年画","省级廉洁文化基地","非遗","廉洁文创"],"year":2018,"summary":"国家级非遗绵竹年画与廉洁文化融合的创作传播基地，四川首批省级廉洁文化基地。以年画这一群众喜闻乐见的形式，创作大量廉洁主题作品并进入村居。","highlights":["廉洁年画主题创作展","年画里的家风与村规民约","可体验的年画印制廉洁课堂"],"story":"年画挂在堂屋，画的是一家人的念想。绵竹的廉洁年画把\"包公掷砚\"\"一钱太守\"画成门神模样，也把\"村务公开\"\"不吃请\"画进新春年货。道理不必高深，家家看得懂、年年贴得起，清风就长在生活里。","quote":"一纸年画贴堂前，清白家风代代传。","phone":null,"official":true},{"id":"deyang-fanjiadayuan","name":"范家大院家风文化园","city":"德阳市","district":"罗江区","address":"万安镇响石村3组","lat":31.307,"lng":104.51,"verify":"verified","categories":["家风家训","清官廉吏"],"tags":["范仲淹后裔","家规家训","川渝好家风环线","古院落"],"year":2018,"summary":"范仲淹后裔聚居的清代院落，园内以《范氏家规》为核心，展示\"先忧后乐\"精神在川西坝子上的家族传承，是\"川渝好家风\"环线点位。","highlights":["《范氏家规》与族谱展","\"先忧后乐\"精神传承展线","古院落家风现场教学"],"story":"范氏后人把《岳阳楼记》里的\"先天下之忧而忧\"写进家规：为官者不得以权谋私，族中子弟犯贪者不得入祠。一座川西院落，接续的是千年前的那句忧乐之问。","quote":"先天下之忧而忧，后天下之乐而乐。","phone":"0838-5977111","official":false},{"id":"deyang-huangjiguang-ji","name":"黄继光纪念馆","city":"德阳市","district":"中江县","address":"凯江镇东河路下段1号","lat":31.033,"lng":104.678,"verify":"verified","categories":["红色廉洁","廉政教育"],"tags":["特级英雄","抗美援朝","爱国主义教育","中江"],"year":1987,"summary":"纪念特级英雄黄继光的专题纪念馆，陈列其生平事迹与上甘岭战役实物，是四川重要的爱国主义教育基地和廉政教育现场教学点。","highlights":["黄继光生平事迹陈列","上甘岭战役场景复原","英雄家书与家风展"],"story":"黄继光在请战书上写\"不立功不下战场\"，牺牲时年仅 21 岁。他留下的家书里劝母亲\"家里的地要种好，不要给政府添麻烦\"。一个农村青年把\"不给组织添麻烦\"当作最后的交代，这份朴素的自律，比任何口号都更有力量。","quote":"不立功不下战场。","phone":null,"official":false},{"id":"mianyang-liangdancheng","name":"中国两弹城","city":"绵阳市","district":"梓潼县","address":"长卿镇长卿村七社","lat":31.618,"lng":105.166,"verify":"verified","categories":["行业清风","红色廉洁"],"tags":["两弹一星","省级廉洁文化基地","科学家精神","川渝好家风环线"],"year":2018,"summary":"中国工程物理研究院院部旧址，邓稼先、于敏等科学家曾在此隐姓埋名研制\"两弹\"。四川首批省级廉洁文化基地，以\"干惊天动地事、做隐姓埋名人\"为精神标识。","highlights":["两弹研制历程与院部旧址","邓稼先旧居与\"两弹元勋\"事迹展","保密与奉献精神专题教育"],"story":"在大山深处的红砖房里，一群最优秀的头脑隐去姓名、断绝对外联系，把青春交给国家。邓稼先去世前，奖金单据上写着二十元。有人问他值不值，他说：\"我不入地狱，谁入地狱。\"清贫与伟大在他们身上不是矛盾，而是同一件事。","quote":"干惊天动地事，做隐姓埋名人。","phone":"0816-5380866","official":true},{"id":"guangyuan-chuanbei-jiafeng-guan","name":"川北家风馆","city":"广元市","district":"利州区","address":"万缘街道通驿路6号万安博物馆3楼","lat":32.421,"lng":105.867,"verify":"verified","categories":["家风家训","廉政教育"],"tags":["省级廉洁文化基地","川北家风","红色家风","川渝好家风环线"],"year":2018,"summary":"四川首批省级廉洁文化基地，以川北地区家风资源为脉络，串联本土先贤家训、红色家风与当代最美家庭故事，是川陕革命老区家风教育的重要阵地。","highlights":["川北先贤家训与族谱长廊","红四方面军时期的家风故事","当代最美家庭与家风课堂"],"story":"广元是川陕革命根据地的重要组成部分，当年许多青年参军前，父母给的不是盘缠而是叮嘱：\"在外莫贪人钱财。\"家风馆把这句话放大在展厅尽头——它朴素得像田埂上的土话，却是一个家庭能给远行人最硬的护身符。","quote":"在外莫贪人钱财，居家莫占人便宜。","phone":"0839-3990708","official":true},{"id":"guangyuan-cangxi-hongjun-du","name":"苍溪红军渡纪念地","city":"广元市","district":"苍溪县","address":"陵江镇红军渡社区（嘉陵江畔）","lat":31.727,"lng":105.934,"verify":"verified","categories":["红色廉洁"],"tags":["红四方面军","强渡嘉陵江","长征出发地","爱国主义教育"],"year":1994,"summary":"红四方面军强渡嘉陵江长征出发地纪念地，含红军渡纪念碑、渡江指挥部旧址与纪念馆，是四川重要的革命传统教育基地。","highlights":["强渡嘉陵江战役陈列","渡江指挥部旧址","红军石刻标语与群众纪律遗迹"],"story":"1935 年，红四方面军从苍溪塔子山下的渡口西渡嘉陵江，开始长征。渡江前，部队把借用的船只、门板逐一登记归还。今天站在渡口，江水依旧，最该记住的或许是那些写在石头上的标语——\"红军是穷人的队伍\"，而队伍之所以是队伍，靠的是纪律。","quote":"红军是穷人的队伍。","phone":null,"official":false},{"id":"guangyuan-mumen-huiyi","name":"木门会议旧址","city":"广元市","district":"旺苍县","address":"木门镇柳树村","lat":32.121,"lng":106.512,"verify":"verified","categories":["红色廉洁"],"tags":["红四方面军","木门会议","扩编整训","革命旧址"],"year":1933,"summary":"1933 年红四方面军在此召开木门会议，决定部队扩编整训、加强纪律建设，是川陕苏区重要的革命历史遗址与廉洁从政教育现场。","highlights":["木门会议历史陈列","川陕苏区纪律建设史料","革命旧址原貌"],"story":"木门会议的一项重要议题是扩编与整训——把队伍带成一支听指挥、守纪律的正规军。川陕苏区能\"赤化全川\"的声势，离不开严格的作风。历史反复证明：队伍的战斗力，往往是从管住自己开始的。","quote":"加强纪律，才能巩固队伍。","phone":null,"official":false},{"id":"suining-pengxi-shufa","name":"蓬溪廉洁书法创作基地","city":"遂宁市","district":"蓬溪县","address":"赤城镇（中国书法之乡·蓬溪）","lat":30.758,"lng":105.708,"verify":"verified","categories":["清官廉吏","廉政教育"],"tags":["中国书法之乡","省级廉洁文化基地","张鹏翮","廉文化书法"],"year":2018,"summary":"依托\"中国书法之乡\"蓬溪的书画传统建设，四川首批省级廉洁文化基地。基地以清代廉吏张鹏翮等本土人物为题材，用书法艺术创作传播廉洁理念。","highlights":["廉洁主题书法作品长廊","清代廉吏张鹏翮史迹展","书法研学与廉洁课堂"],"story":"张鹏翮官至河道总督、吏部尚书，一生治河、治吏，以清操闻名，康熙帝称其\"天下廉吏，无出其右\"。蓬溪人把他的话写成字、刻成碑。笔墨千年不褪色，清廉二字也是一样。","quote":"一丝一粒，我之名节；一厘一毫，民之脂膏。","phone":null,"official":true},{"id":"suining-huang-e-jiafeng","name":"黄峨家风教育基地","city":"遂宁市","district":"安居区","address":"玉丰镇黄峨古镇","lat":30.397,"lng":105.421,"verify":"verified","categories":["家风家训","清官廉吏"],"tags":["黄峨","杨升庵之妻","川渝好家风环线","散曲文化"],"year":2018,"summary":"以明代才女黄峨（杨升庵之妻）故里为核心建成的家风教育基地，\"川渝好家风\"环线点位，讲述黄峨与杨升庵夫妻相守、清贫自持的家风故事。","highlights":["黄峨生平与《寄外》诗作展","黄杨两家家风传承展线","古镇家风讲堂"],"story":"杨升庵谪戍云南三十年，黄峨留在四川新都，以诗书自遣、以清贫自守，写下\"寄外\"之作传世。夫妻两地，家无余财而名节不亏。家风教育讲黄峨，讲的是\"守得住\"三个字——守得住清贫，也守得住情义与规矩。","quote":"雁飞曾不到衡阳，锦字何由寄永昌。","phone":"0825-8661000","official":false},{"id":"suining-kuangjixun-ji","name":"旷继勋纪念馆","city":"遂宁市","district":"蓬溪县","address":"赤城镇继勋公园","lat":30.757,"lng":105.712,"verify":"est","categories":["红色廉洁","廉政教育"],"tags":["旷继勋","蓬溪起义","红军将领","革命烈士"],"year":2011,"summary":"纪念红军高级将领旷继勋的专题纪念馆。1929 年他在蓬溪发动起义，建立四川第一个县级苏维埃政权，纪念馆展示其革命生涯与清廉品格。","highlights":["蓬溪起义历史陈列","旷继勋生平事迹展","革命烈士廉洁自律故事"],"story":"旷继勋从川军旅长成长为红军军长，1933 年被错杀于通江，年仅 36 岁。他一生行军打仗，从不置私产。纪念馆里那只旧皮箱，装过命令、地图和文件，唯独没有家财。忠诚二字，有时要用最沉重的代价来写。","quote":"革命者当以天下为家，岂能置私产。","phone":null,"official":false},{"id":"neijiang-longchang-shipaifang","name":"隆昌石牌坊群","city":"内江市","district":"隆昌市","address":"城区北关道观坪（北关石牌坊景区，另有南关春牛坪）","lat":29.3396,"lng":105.2881,"verify":"verified","categories":["清官廉吏","家风家训"],"tags":["省级廉洁文化基地","石牌坊","德政牌坊","明清"],"year":2018,"summary":"现存明清石牌坊 17 座，其中德政坊、功德坊集中褒扬本地廉能官吏与乡贤，四川首批省级廉洁文化基地，被称为\"立体史书\"。","highlights":["德政牌坊与廉吏碑传","\"德政\"与\"节孝\"牌坊群","牌坊铭文中的为官之道"],"story":"隆昌牌坊多为民众为纪念清官而建。\"德政坊\"上刻的不是官职，而是减赋、赈灾、修桥的具体政绩。百姓把口碑刻在石头上，几百年风吹不动。这或许是廉洁教育最古老的载体：让为政者的名声，交给身后的一代代路人评价。","quote":"政声人去后，民意闲谈时。","phone":null,"official":true},{"id":"neijiang-fanchangjiang-ji","name":"范长江纪念馆","city":"内江市","district":"东兴区","address":"田家镇正子村（长江新闻文化园）","lat":29.5723,"lng":105.0886,"verify":"verified","categories":["行业清风","红色廉洁"],"tags":["范长江","新闻巨子","长江新闻文化园","川渝好家风环线"],"year":2009,"summary":"中国新闻巨子范长江的故里纪念馆，含长江新闻文化园。以\"真实报道、不畏艰险\"的职业精神为主线，是新闻界与党员干部作风建设教育基地。","highlights":["范长江生平与新闻作品展","《中国的西北角》采访路线图","新闻职业道德与清风讲堂"],"story":"1935 年，范长江只身深入西北采访，写下《中国的西北角》，第一次向全国公开报道红军长征。他一生秉持\"不唯上、不唯书、只唯实\"，敢讲真话。新闻的清风与为政的清风同理：都靠事实立身。","quote":"手无寸铁兵百万，力举千钧纸一张。","phone":"0832-2543333","official":false},{"id":"leshan-guomoruo-guju","name":"郭沫若故居纪念馆","city":"乐山市","district":"沙湾区","address":"铜河街道沫水社区文豪路351号","lat":29.4122,"lng":103.5495,"verify":"verified","categories":["家风家训","清官廉吏"],"tags":["省级廉洁文化基地","郭沫若","家风家训","沙湾"],"year":2018,"summary":"郭沫若出生与少年时代生活地，四川首批省级廉洁文化基地。纪念馆以郭氏家训、母亲教诲与郭氏家族故事为核心，展示\"勤俭、读书、报国\"的家风底色。","highlights":["郭氏家训与母亲杜氏教诲展","郭沫若生平与文学成就陈列","家风与家教互动课堂"],"story":"郭沫若回忆，母亲教给他\"做人要正、做事要勤\"。郭家老宅的对联写着\"传家有道惟存厚，处世无奇但率真\"。一个家族的文化积累，往往不在田产多少，而在一代代人对厚道与正直的坚持。","quote":"传家有道惟存厚，处世无奇但率真。","phone":"0833-5201222","official":true},{"id":"leshan-dingyoujun-ji","name":"丁佑君烈士纪念馆","city":"乐山市","district":"五通桥区","address":"菩提山上","lat":29.4022,"lng":103.8102,"verify":"verified","categories":["红色廉洁","廉政教育"],"tags":["丁佑君","革命烈士","西康剿匪","青年教育"],"year":1985,"summary":"纪念 1950 年在西康剿匪中牺牲的烈士丁佑君。她牺牲时年仅 19 岁，纪念馆以\"青春献给信仰\"为主题，是青年党员和团员教育的重要基地。","highlights":["丁佑君生平事迹陈列","烈士遗物与手稿","青年理想信念教育课堂"],"story":"丁佑君本是西康人民革命干部学校学员，主动要求到最危险的地方工作。被捕后面对威逼利诱，她回答\"我是来为人民服务的\"。19 岁的生命很短，但她用一句话把\"为了谁\"这个根本问题答完了。","quote":"我是来为人民服务的。","phone":null,"official":false},{"id":"nanchong-zhude-guli","name":"朱德故里","city":"南充市","district":"仪陇县","address":"马鞍镇大湾路47号","lat":31.517,"lng":106.573,"verify":"verified","categories":["红色廉洁","家风家训"],"tags":["朱德","省级廉洁文化基地","川渝好家风环线","5A 景区"],"year":2018,"summary":"朱德同志故居所在地，四川首批省级廉洁文化基地。景区含朱德故居、朱德同志故居纪念馆、朱德父母墓与琳琅山，是四川最具影响力的红色廉洁教育目的地。","highlights":["朱德同志故居纪念馆","朱德\"约法三章\"与\"三不准\"家风展","朱德生活实物：旧棉衣、补丁袜"],"story":"朱德给家人立下\"三不准\"：不准搭乘他的汽车，不准以他的名义去办事，不准亲朋好友去麻烦他。他逝世前把仅有的两万元存款作为最后一次党费交给组织。共和国元帅的账本上，没有一分钱说不清。清廉二字，他践行了一生。","quote":"革命者的遗产不是金钱，而是革命精神。","phone":"13629050990","official":true},{"id":"nanchong-zhanglan-guju","name":"张澜故居","city":"南充市","district":"西充县","address":"莲池镇观音堂村","lat":30.947,"lng":105.852,"verify":"verified","categories":["清官廉吏","家风家训"],"tags":["张澜","民盟主席","川北圣人","表方家风"],"year":2006,"summary":"中央人民政府原副主席、民盟创始人张澜先生故里，含故居、张澜生平陈列馆与家风馆。以\"表方家风\"和\"布衣省长\"的清白人生为教育核心。","highlights":["张澜生平事迹陈列馆","张氏\"表方家风\"家训展","先生手稿与布衣生活实物"],"story":"张澜曾任四川省长，却被称为\"布衣省长\"：青布长衫、布鞋粗食，任上拒绝一切馈赠。他把家训概括为\"勤劳、节俭、正直、爱国\"。新中国成立时，他已是古稀老人，仍把一生积蓄用于教育事业。乡人送他四个字：川北圣人。","quote":"人不可以不自爱，不可以不自修，不可以不自尊，不可以不自强。","phone":null,"official":false},{"id":"nanchong-luoruiqing-guju","name":"罗瑞卿故居","city":"南充市","district":"顺庆区","address":"舞凤街道清泉坝将军路25号","lat":30.831,"lng":106.107,"verify":"verified","categories":["红色廉洁","清官廉吏"],"tags":["罗瑞卿","开国大将","公安工作奠基人","廉政教育"],"year":1986,"summary":"开国大将、新中国公安工作奠基人罗瑞卿同志故里，含故居与生平事迹陈列室，展示其从严治警、两袖清风的革命生涯。","highlights":["罗瑞卿生平事迹陈列","从严治警与公安装备实物","大将家风与子女教育故事"],"story":"罗瑞卿主政公安工作十年，出差从不许迎送，家人不得打着他的旗号办事。他给子女定下规矩：\"我的功劳是党的，不是你们的。\"1978 年他病逝前，仍在关心公安队伍的作风建设。一个把\"管人\"的岗位做到极致的将军，先管住的正是自己和家人。","quote":"我的功劳是党的，不是你们的。","phone":null,"official":false},{"id":"nanchong-zhangsier-ji","name":"张思德纪念馆","city":"南充市","district":"仪陇县","address":"新政镇春晖路一段（仪陇县文化中心内）","lat":31.27,"lng":106.291,"verify":"verified","categories":["红色廉洁","廉政教育"],"tags":["为人民服务","张思德","炭窑","宗旨教育"],"year":2009,"summary":"纪念\"为人民服务\"的典范张思德同志。1944 年他在陕北安塞烧炭时因炭窑崩塌牺牲，毛泽东同志发表《为人民服务》演讲悼念。","highlights":["张思德生平事迹陈列","《为人民服务》演讲史料","烧炭场景复原与宗旨教育课堂"],"story":"张思德一生职务不高：红军战士、通信班长、烧炭队长。哪里需要就去哪，从不计较职位。他牺牲时 29 岁，留下的遗物屈指可数。毛泽东同志说，他是\"为人民利益而死，就比泰山还重\"。岗位无贵贱，干净与担当才是分量所在。","quote":"为人民利益而死，就比泰山还重。","phone":null,"official":false},{"id":"nanchong-langzhong-zhengde","name":"阆中古城政德文化教育基地","city":"南充市","district":"阆中市","address":"阆中古城学道街78号（川北道贡院）","lat":31.559,"lng":106.005,"verify":"verified","categories":["清官廉吏","廉政教育"],"tags":["政德文化","川北道贡院","川渝好家风环线","科举廉洁"],"year":2019,"summary":"依托阆中古城贡院、道台衙门等资源打造的政德教育基地，\"川渝好家风\"环线点位。以科举取士的公正、地方官吏的政德为切入点，讲\"为政之德\"。","highlights":["川北道贡院科举制度与考纪展","古代地方官政德展厅","\"官箴碑\"与为政格言"],"story":"贡院是古代选拔人才的地方，夹带、替考者要戴枷示众，考官舞弊者革职治罪——制度设计里透着\"把权力关进笼子\"的朴素智慧。阆中的官箴碑上刻着\"吏不畏吾严而畏吾廉\"，一个\"廉\"字，管住了千年吏治。","quote":"吏不畏吾严而畏吾廉，民不服吾能而服吾公。","phone":"18384053255","official":false},{"id":"nanchong-zhanglan-memorial-2","name":"南充市廉政教育基地","city":"南充市","district":"顺庆区","address":"南充市顺庆区（市纪委监委廉政教育中心）","lat":30.847,"lng":106.083,"verify":"est","categories":["廉政教育"],"tags":["警示教育","以案明纪","纪法课堂","市级基地"],"year":null,"summary":"南充市纪委监委建设的廉政教育阵地，以警示教育与纪法学习为主，通过本地典型案例剖析、忏悔录现场教学等形式，为党员干部提供\"不敢腐、不能腐、不想腐\"的警醒课堂。","highlights":["本地典型案例警示展","忏悔录与处分决定现场教学","纪法知识测试与承诺践诺"],"story":"警示教育最动人的往往不是展板，而是展板上熟悉的名字。从\"破纪\"到\"破法\"，几乎每一步都始于\"这点小事不算啥\"的自我说服。把别人的教训当镜子，比把别人的成绩当目标更有价值。","quote":"见善如不及，见不善如探汤。","phone":null,"official":false},{"id":"meishan-sansuci","name":"眉山三苏祠","city":"眉山市","district":"东坡区","address":"纱縠行南段72号","lat":30.043,"lng":103.834,"verify":"verified","categories":["家风家训","清官廉吏"],"tags":["三苏","省级廉洁文化基地","川渝好家风环线","读书正业"],"year":2018,"summary":"苏洵、苏轼、苏辙父子故居祠堂，四川首批省级廉洁文化基地。三苏家风以\"读书正业、孝慈仁爱、非义不取、为政清廉\"为纲，是全国知名的家风教育样本。","highlights":["三苏家风家训展（程夫人教子故事）","苏轼\"苟非吾之所有，虽一毫而莫取\"主题展","苏宅古井、丹荔、木假山堂古迹"],"story":"苏轼在《赤壁赋》中写\"苟非吾之所有，虽一毫而莫取\"；被贬黄州、惠州、儋州，三起三落，从不以权谋私。母亲程夫人曾教他\"汝能安贫守分，吾愿足矣\"。一门三文豪，家训只讲两件事：读书，做人。","quote":"苟非吾之所有，虽一毫而莫取。","phone":"028-38220186","official":true},{"id":"meishan-dayatang","name":"大雅堂省级廉洁文化基地","city":"眉山市","district":"丹棱县","address":"齐乐镇素翁路1号","lat":30.014,"lng":103.518,"verify":"verified","categories":["清官廉吏","家风家训"],"tags":["大雅堂","家风家训","丹棱","川渝好家风环线"],"year":2018,"summary":"重建的宋代\"大雅堂\"所在地，省级廉洁文化基地。以丹棱本土家风家训资源与黄庭坚、杨素等人物史迹为核心，讲\"雅正\"文化中的清廉底蕴。","highlights":["家风家训主题展区","大雅文化历史陈列","丹棱先贤廉政故事墙"],"story":"\"大雅\"取自《诗经》，本意是正声、正道。基地以\"雅\"释\"廉\"：所谓雅，不是风花雪月，而是把持得住分寸、守得住底线。小县城的一堂家训课，讲的是大雅之堂上的规矩。","quote":"雅者，正也。","phone":"028-35093646","official":true},{"id":"yibin-bashu-jiafeng","name":"巴蜀家风传承示范基地","city":"宜宾市","district":"南溪区","address":"裴石镇月亮湾交通路59号（巴蜀家风馆）","lat":28.8553,"lng":104.9807,"verify":"verified","categories":["家风家训","廉政教育"],"tags":["省级廉洁文化基地","巴蜀家风","川渝好家风环线","家风馆"],"year":2018,"summary":"四川首批省级廉洁文化基地，以\"家\"为主题、以\"风\"为脉络，系统梳理巴蜀名门家训与红色家风，配套家风讲堂与研学课程。","highlights":["巴蜀家风馆主展区","名门家训与家书长廊","家风研学与主题党日课堂"],"story":"基地把巴蜀家风拆成三个问题：祖先留下什么？父母教了什么？我们要交给孩子什么？很多参观者答完第三问才明白，家风不是遗产分配，而是一场跨越三代的接力。","quote":"家之兴替，在于礼义，不在于富贵贫贱。","phone":"0831-3394101","official":true},{"id":"yibin-zhaoyiman-ji","name":"赵一曼纪念馆","city":"宜宾市","district":"翠屏区","address":"翠屏路239号（翠屏山麓）","lat":28.7792,"lng":104.6073,"verify":"verified","categories":["红色廉洁","家风家训"],"tags":["赵一曼","抗日英雄","川渝好家风环线","爱国主义教育"],"year":1960,"summary":"纪念抗日民族英雄赵一曼的专题纪念馆，\"川渝好家风\"环线点位。以她写给儿子的遗书为核心展品，讲信仰、亲情与家国。","highlights":["赵一曼生平事迹陈列","写给儿子宁儿的遗书手迹","东北抗日联军史料展"],"story":"赵一曼牺牲前在囚车上写下给儿子的信：\"母亲不用千言万语来教育你，就用实行来教育你。\"她没能陪孩子长大，却留下了一份最重的家书。家风教育里最硬的一课，是父母把自己活成了教材。","quote":"母亲不用千言万语来教育你，就用实行来教育你。","phone":"0831-3789099","official":false},{"id":"guangan-dengxiaoping-guli","name":"邓小平故里","city":"广安市","district":"广安区","address":"协兴镇牌坊村420号","lat":30.511,"lng":106.606,"verify":"verified","categories":["红色廉洁","家风家训"],"tags":["邓小平","省级廉洁文化基地","川渝好家风环线","5A 景区"],"year":2018,"summary":"邓小平同志故居所在地，四川首批省级廉洁文化基地。景区含邓小平故居、陈列馆、缅怀馆与邓家老井，是改革开放史与廉洁从政教育的重要阵地。","highlights":["邓小平故居陈列馆","邓氏家训与\"家规十条\"展","缅怀馆与改革开放历程展"],"story":"邓小平晚年叮嘱家人：\"不要搞特殊化。\"他给中央写信要求不搞个人崇拜、身后不留骨灰、不设故居纪念馆。一位老人的三次\"不要\"，把权力看得很轻，把规矩看得很重。","quote":"我是中国人民的儿子，我深情地爱着我的祖国和人民。","phone":"0826-2413858","official":true},{"id":"guangan-huayingshan","name":"华蓥山游击队纪念馆","city":"广安市","district":"华蓥市","address":"华蓥山旅游区（石林景区内）","lat":30.418,"lng":106.755,"verify":"est","categories":["红色廉洁"],"tags":["华蓥山游击队","红岩精神","双枪老太婆","革命遗址"],"year":2005,"summary":"展示华蓥山游击队在川东地区坚持武装斗争历史的纪念馆，与重庆渣滓洞、白公馆史料相互呼应，是川东红色教育与廉洁教育基地。","highlights":["华蓥山游击队斗争史陈列","红岩英烈事迹展","游击队遗址徒步教学线路"],"story":"华蓥山游击队长期在极其艰苦的条件下坚持斗争，队伍靠\"自带干粮去革命\"的自觉维系。史料里有队员把家里仅有的口粮交给组织、自己挖野菜的记录。信仰不抽象，它体现在最饿的时候先想到谁。","quote":"自带干粮去革命。","phone":null,"official":false},{"id":"dazhou-shenjianyuan","name":"神剑园","city":"达州市","district":"通川区","address":"罗江镇将军路288号","lat":31.273,"lng":107.523,"verify":"verified","categories":["红色廉洁","行业清风"],"tags":["张爱萍","省级廉洁文化基地","两弹一星","国防科技"],"year":2018,"summary":"以张爱萍将军故居为核心，含达州红军文化陈列馆与两弹一星事业展，四川首批省级廉洁文化基地。以\"将军与科学家\"的家国情怀讲清正廉洁。","highlights":["张爱萍将军故居与生平陈列","达州红军文化陈列馆","两弹一星功勋与国防科技展"],"story":"张爱萍将军既是指挥员，也是\"两弹一星\"事业的领导者之一。他给家人立下规矩：不许打他的旗号。老屋的陈设几十年未变。将军的剑是护国的，剑鞘上不该刻私人的名字。","quote":"为国为民，虽死不悔。","phone":"0818-7231991","official":true},{"id":"dazhou-hongjun-wenhua-chenlie","name":"达州红军文化陈列馆","city":"达州市","district":"通川区","address":"罗江镇神剑园景区内","lat":31.272,"lng":107.521,"verify":"est","categories":["红色廉洁"],"tags":["川陕苏区","红军文化","达州","革命传统"],"year":2014,"summary":"系统展示达州籍红军将士与川陕苏区革命斗争的专题馆，与神剑园一体，是达州开展革命传统和廉洁教育的重要场所。","highlights":["达州红军将士群像展","川陕苏区群众工作史料","红军石刻标语拓片"],"story":"川陕苏区时期，达州有十余万人参加红军。馆里有一面墙，刻着密密麻麻的姓名——他们中许多人没有留下照片。廉洁教育的起点，是承认今天的安稳来自这些名字。","quote":"忘记过去，就意味着背叛。","phone":null,"official":false},{"id":"yaan-angsidu-daduhe","name":"中国工农红军强渡大渡河纪念馆","city":"雅安市","district":"石棉县","address":"安顺场镇安顺村","lat":29.235,"lng":102.348,"verify":"verified","categories":["红色廉洁","廉政教育"],"tags":["省级廉洁文化基地","安顺场","十七勇士","长征"],"year":2018,"summary":"红军长征强渡大渡河纪念地，四川首批省级廉洁文化基地。含纪念馆、渡口遗址与红军长征精神教育园区，以\"十七勇士\"事迹讲述将士们的纪律与牺牲。","highlights":["强渡大渡河纪念馆","安顺场渡口遗址与纪念碑","红军先遣队纪律故事展"],"story":"十七名勇士乘一条小船，在敌人枪口下强渡天险。出发前，每人留下一份\"遗物清单\"——多是几件旧衣、一双草鞋。生死关头最能看清一个人看重什么。他们把命交给理想时，也把私心留在了岸上。","quote":"翼王悲剧地，红军胜利场。","phone":null,"official":true},{"id":"yaan-jiajinshan-ji","name":"红军长征翻越夹金山纪念馆","city":"雅安市","district":"宝兴县","address":"穆坪镇（夹金山下）","lat":30.371,"lng":102.813,"verify":"verified","categories":["红色廉洁"],"tags":["夹金山","长征","雪山草地","革命传统"],"year":2006,"summary":"纪念中央红军翻越长征途中第一座大雪山——夹金山的专题馆。以红军在极端环境中互助前行的事迹，讲艰苦奋斗与集体主义。","highlights":["翻越雪山历史陈列","红军过雪山实物与影像","雪山徒步体验与现场教学"],"story":"夹金山海拔四千余米，红军战士身着单衣翻越，靠相互搀扶走到山顶。有回忆录记载，炊事员背着铜锅倒在雪里，怀里还护着部队的口粮。艰苦岁月里\"先有集体、后有自己\"的本能，正是作风的根。","quote":"红军不怕远征难，万水千山只等闲。","phone":null,"official":false},{"id":"bazhong-wangping-lingyuan","name":"川陕革命根据地红军烈士陵园","city":"巴中市","district":"通江县","address":"沙溪镇王坪村","lat":32.112,"lng":107.478,"verify":"verified","categories":["红色廉洁","廉政教育"],"tags":["省级廉洁文化基地","王坪","红军烈士","无字碑"],"year":2018,"summary":"全国规模最大的红军烈士陵园，安葬两万余名红军烈士，四川首批省级廉洁文化基地。以\"无字碑\"与烈士英名墙为核心，开展理想信念和廉洁教育。","highlights":["烈士陵园与英名墙","无名烈士\"无字碑\"","铁血丹心纪念馆实景教学"],"story":"陵园里有一块\"无字碑\"，下面长眠的是成千上万没有留下姓名的烈士。他们生前不留名、身后不留财。站在碑前，很容易想到一个问题：一个人到底图什么？答案写在满山的墓碑里——图的是后人过得更好。","quote":"为有牺牲多壮志，敢教日月换新天。","phone":null,"official":true},{"id":"bazhong-jiangshuai-beilin","name":"川陕苏区将帅碑林","city":"巴中市","district":"巴州区","address":"南龛景区（城南）","lat":31.843,"lng":106.75,"verify":"est","categories":["红色廉洁"],"tags":["将帅碑林","川陕苏区","南龛","爱国主义教育"],"year":1993,"summary":"全国最大的红军将帅碑林，镌刻红四方面军将士名录与题词，是巴中红色文化地标与革命传统教育基地。","highlights":["将帅碑林石刻长廊","红四方面军将士名录","南龛摩崖造像与红色文化联展"],"story":"碑林里刻着上万名红军将士的名字，多数是普通战士。把普通人的名字刻在石头上，是这片土地对\"谁创造了历史\"的回答。廉洁教育要讲的，正是这种把功劳归于集体的清醒。","quote":"群众是真正的英雄。","phone":null,"official":false},{"id":"ziyang-chenyi-guju","name":"陈毅故居","city":"资阳市","district":"乐至县","address":"劳动镇旧居村","lat":30.311,"lng":105.148,"verify":"verified","categories":["红色廉洁","家风家训"],"tags":["陈毅","省级廉洁文化基地","川渝好家风环线","元帅故里"],"year":2018,"summary":"陈毅元帅出生地，四川首批省级廉洁文化基地。含陈毅故居、陈毅纪念馆与诗书广场，以\"手莫伸\"诗碑和元帅家风为核心教育内容。","highlights":["《手莫伸》诗碑与廉洁主题园","陈毅故居与生平陈列馆","陈氏家风家训展"],"story":"陈毅在《感事书怀·七古·手莫伸》中自警：\"手莫伸，伸手必被捉。\"他把这首诗当作座右铭，也用来告诫子女和身边人。元帅的诗句直白如口令，却道尽了权力与自律的全部关系。","quote":"手莫伸，伸手必被捉。","phone":"028-23336012","official":true},{"id":"ziyang-chenyi-ji","name":"陈毅纪念馆","city":"资阳市","district":"乐至县","address":"劳动镇旧居村（陈毅故里景区内）","lat":30.312,"lng":105.15,"verify":"verified","categories":["红色廉洁","家风家训"],"tags":["陈毅","川渝好家风环线","元帅生平","诗书文化"],"year":2011,"summary":"陈毅故里景区核心场馆之一，\"川渝好家风\"环线点位。以文物、手稿、诗词展现陈毅同志革命生涯与清正家风，与故居形成完整参观序列。","highlights":["陈毅生平事迹陈列","元帅诗词与手稿展","家风家教专题展区"],"story":"陈毅任上海市长时，得知妹妹想让他帮忙安排工作，回信写道\"要想办法自己解决\"。亲戚说他\"官大了不认人\"，他说：\"共产党的官，认的是规矩。\"一个家庭的清白，往往就立在这种\"不近人情\"上。","quote":"我要为众人，营私以为羞。","phone":"028-23336012","official":false},{"id":"aba-hongjun-beibei-yuan","name":"红军长征纪念碑碑园","city":"阿坝藏族羌族自治州","district":"松潘县","address":"川主寺镇元宝山","lat":32.895,"lng":103.582,"verify":"verified","categories":["红色廉洁"],"tags":["省级廉洁文化基地","长征总碑","川主寺","雪山草地"],"year":2018,"summary":"全国唯一的红军长征纪念碑总碑所在地，四川首批省级廉洁文化基地。碑园以\"告别苏区\"\"艰苦历程\"等大型雕塑群，再现红军过雪山草地的历程。","highlights":["长征纪念碑总碑与大型雕塑群","雪山草地艰苦历程展","长征精神现场教学"],"story":"阿坝是红军长征停留时间最长、条件最苦的地区。草地行军时，战士们把仅有的青稞面留给伤员，自己煮皮带充饥。纪念碑高耸在川主寺，纪念的不只是胜利，更是绝境中人对人的托付。","quote":"红军都是钢铁汉，千锤百炼不怕难。","phone":null,"official":true},{"id":"aba-baxi-huiyi","name":"巴西会议旧址","city":"阿坝藏族羌族自治州","district":"若尔盖县","address":"巴西镇班佑村","lat":33.312,"lng":102.978,"verify":"est","categories":["红色廉洁"],"tags":["巴西会议","若尔盖","长征","北上方针"],"year":1935,"summary":"1935 年 9 月中共中央在此召开政治局会议（巴西会议），确定北上方针。旧址为藏式寺院建筑，是长征途中重要的历史见证地。","highlights":["巴西会议历史陈列","中共中央长征在川西北史料","班佑草地与旧址原貌"],"story":"巴西会议在最危急的关头召开，纠正了分裂倾向，作出北上的抉择。会议旧址是一间朴素的小屋，桌椅粗陋。历史的走向有时就是在这样的屋子里被定下来的——决策的分量，从来不取决于会场的气派。","quote":"北上是唯一正确的方针。","phone":null,"official":false},{"id":"aba-lianghekou-huiyi","name":"两河口会议纪念地","city":"阿坝藏族羌族自治州","district":"小金县","address":"两河口镇","lat":31.286,"lng":102.617,"verify":"est","categories":["红色廉洁"],"tags":["两河口会议","懋功会师","长征","北上抗日"],"year":1935,"summary":"1935 年 6 月中央红军与红四方面军懋功会师后，中共中央在此召开政治局会议（两河口会议），确定北上抗日方针。","highlights":["两河口会议旧址与陈列","懋功会师历史展","关帝庙旧址建筑"],"story":"懋功会师是长征中的大喜事，但两河口会议更重要的成果是统一了方向：北上抗日。会师之后不搞山头、不争高低，把队伍拧成一股绳——团结本身，就是一种纪律。","quote":"团结就是力量。","phone":null,"official":false},{"id":"ganzi-ludingqiao","name":"红军飞夺泸定桥纪念碑公园","city":"甘孜藏族自治州","district":"泸定县","address":"泸桥镇（大渡河畔）","lat":29.915,"lng":102.234,"verify":"verified","categories":["红色廉洁"],"tags":["省级廉洁文化基地","泸定桥","二十二勇士","长征"],"year":2018,"summary":"纪念红军飞夺泸定桥的专题纪念公园，四川首批省级廉洁文化基地。含纪念碑、纪念馆与泸定桥铁索桥本体，是长征精神教育的标志性场所。","highlights":["飞夺泸定桥纪念馆","二十二勇士事迹与姓名墙","泸定桥铁索桥现场体验"],"story":"1935 年 5 月，二十二名突击队员冒着弹雨攀铁索过河，夺下泸定桥。他们中多数人没有留下完整姓名。桥上的十三条铁索至今仍在，人走上去摇晃不止——正是这种摇晃，让\"信仰\"两个字有了身体的重量。","quote":"大渡桥横铁索寒。","phone":null,"official":true},{"id":"ganzi-ludingqiao-chenlie","name":"泸定桥革命文物陈列馆","city":"甘孜藏族自治州","district":"泸定县","address":"泸桥镇红军路","lat":29.914,"lng":102.233,"verify":"est","categories":["红色廉洁"],"tags":["革命文物","长征","泸定","爱国主义教育"],"year":1980,"summary":"与泸定桥一体的革命文物陈列馆，展出红军长征在甘孜的文献、武器与生活实物，是甘孜州重要的革命传统教育基地。","highlights":["红军长征在甘孜史料展","革命文物与红军生活实物","藏区群众支援红军故事展"],"story":"红军经过藏区时严格执行民族政策与群众纪律，不进民房、不扰寺院，用行动赢得信任。陈列馆里有藏区群众为红军带路、送粮的记录。作风好不好，当地百姓最先知道。","quote":"军爱民，民拥军。","phone":null,"official":false},{"id":"liangshan-yihai-jiemeng","name":"彝海结盟纪念馆","city":"凉山彝族自治州","district":"冕宁县","address":"彝海镇彝海村","lat":28.732,"lng":102.189,"verify":"verified","categories":["红色廉洁"],"tags":["省级廉洁文化基地","刘伯承","小叶丹","民族团结"],"year":2018,"summary":"纪念 1935 年刘伯承与彝族首领小叶丹\"彝海结盟\"的专题馆，四川首批省级廉洁文化基地。以民族团结与红军民族政策为核心内容。","highlights":["彝海结盟纪念馆与结盟遗址","红军民族政策史料展","彝海湖畔现场教学"],"story":"刘伯承与小叶丹在彝海边歃血为盟，红军顺利通过彝区。结盟靠的不是武力，而是尊重与守信——红军承诺不侵犯彝族同胞利益，就一丝不苟地做到了。政策的可信度，来自说到做到。","quote":"彝汉一家亲。","phone":null,"official":true},{"id":"liangshan-huili-huiyi","name":"会理会议纪念地","city":"凉山彝族自治州","district":"会理市","address":"城北街道铁厂村（会理会议遗址）","lat":26.686,"lng":102.245,"verify":"est","categories":["红色廉洁"],"tags":["会理会议","长征","巧渡金沙江","革命遗址"],"year":1935,"summary":"1935 年 5 月中央红军在会理召开政治局扩大会议（会理会议），统一战略思想、维护团结。遗址现为会理重要的红色教育基地。","highlights":["会理会议历史陈列","巧渡金沙江与围攻会理史料","会议遗址原貌"],"story":"会理会议的核心议题之一是维护团结、统一指挥。长征路上的每一次危机，最终都靠纪律与共识化解。一个队伍能不能走远，看的不是顺境时的热闹，而是逆境时听不听指挥。","quote":"步调一致才能得胜利。","phone":null,"official":false},{"id":"liangshan-jiefang-jinianta","name":"凉山彝族奴隶社会博物馆","city":"凉山彝族自治州","district":"西昌市","address":"泸山景区（邛海之滨）","lat":27.863,"lng":102.253,"verify":"est","categories":["行业清风","廉政教育"],"tags":["社会进步","民族团结","凉山","爱国主义教育"],"year":1985,"summary":"全国唯一的彝族奴隶社会专题博物馆，展示凉山从奴隶社会到社会主义社会的历史跨越，是民族团结进步与感恩奋进教育的重要场所。","highlights":["凉山社会历史变迁展","民主改革与民族团结史料","新旧凉山对比专题"],"story":"从\"一步跨千年\"的社会变革，到脱贫攻坚中的凉山巨变，这片土地的历史证明了一个朴素的道理：制度的进步，最终要落到普通人能不能过上好日子上。","quote":"一步跨千年。","phone":null,"official":false},{"id":"nanchong-zhanglan-jiafeng-guan","name":"张澜故居 · 西充家风馆","city":"南充市","district":"西充县","address":"莲池镇观音堂村（张澜故里旅游区内，原张家沟小学改建）","lat":30.9236,"lng":105.8342,"verify":"est","categories":["清官廉吏","家风家训","廉政教育"],"tags":["张澜","表方家风","四勉一戒","家风馆"],"year":2020,"summary":"张澜故居为全国重点文物保护单位，2020 年在景区内利用原张家沟小学改建西充家风馆，设家风庭院与室内展区约 300 平方米，展示中华传统家风与张澜\"四勉一戒\"家规，是川北重要的家风家训教育阵地。","highlights":["张澜家训\"四勉一戒\"展陈","家风庭院与家训长廊景观节点","与民盟历史陈列馆形成\"家风 + 统战\"组合线路"],"story":"张澜任四川省省长、成都大学校长期间，始终布衣蔬食、不受馈赠。有人以重金求他通融人事，他当即退回并严词拒绝，时人称之为\"布衣省长\"。新中国成立后他任中央人民政府副主席，仍穿粗布长衫、居所简朴，把家中藏书捐给学校。他给子女立下\"四勉一戒\"，反复告诫\"断不可以自欺\"。家风馆建在一所小学旧址上，寓意家风如课、代代相传。","quote":"人不可以不自爱，不可以不自修，不可以不自尊，不可以不自强，而断不可以自欺。","phone":"0817-4713291","official":false},{"id":"nanchong-luoruiqing-ji","name":"罗瑞卿纪念馆","city":"南充市","district":"顺庆区","address":"将军路25号","lat":30.8114,"lng":106.0875,"verify":"est","categories":["红色廉洁","家风家训","廉政教育"],"tags":["开国大将","廉政教育专栏","公安政法传统","罗氏家训"],"year":1988,"summary":"依托开国大将罗瑞卿故居建设的专题纪念馆，设生平事迹陈列室、影视放映厅与\"廉政教育\"专题栏目，展示其清正为官、严格治家的革命生涯，是南充城区最重要的红色廉洁教育点位。","highlights":["罗氏家训\"忠孝仁爱、勤耕苦学、克勤克俭\"","馆内\"廉政教育\"专题展线","与社区微型家风馆联动形成\"1+N\"廉洁家风阵地"],"story":"罗瑞卿担任新中国首任公安部长期间，对家人立下铁规：不许家人打他的旗号办事，不许亲友到公安部\"走后门\"。家乡亲属多次请求安排工作，均被他婉言谢绝。他反复教育子女\"要靠自己的本事吃饭\"，生活上不许有半点特殊。将军故居旁的那条将军路，是他一生最直白的注脚——名头是人民给的，不能用来换私利。","quote":"忠孝仁爱、勤耕苦学、克勤克俭。","phone":"0817-2601148","official":false},{"id":"nanchong-luoruiqing-weixing-jiafeng-guan","name":"罗瑞卿主题微型家风馆（清源社区）","city":"南充市","district":"顺庆区","address":"舞凤街道清源社区居民委员会内","lat":30.8341,"lng":106.1038,"verify":"est","categories":["家风家训"],"tags":["社区微馆","结对共建","罗氏家训","顺庆三微家风阵地"],"year":2023,"summary":"由顺庆区舞凤街道清源社区与罗瑞卿纪念馆结对共建的社区级微型家风馆，2023 年初建成开放，以罗瑞卿家风故事为主线，把大将家风送到居民楼下，是廉洁文化\"进社区\"的基层样本。","highlights":["利用社区闲置空间建设的\"袖珍馆\"，不增加财政负担","系统展示罗氏家训家规与家族文化","带动陈寿、谯周、纪信、张澜等主题微馆陆续布点"],"story":"\"以前想让孩子接受家风教育，只能去罗瑞卿纪念馆，要预约、人又多、离家还远。现在在社区楼下就能参观。\"一位带着孩子的市民这样说。这间不大的社区微馆，把开国大将的家风故事搬到了居民楼下。顺庆区据此探索\"家风微馆 + 家风微课 + 家风微景\"的三微模式，让廉洁文化融入日常生活而不是只停在展板上。","quote":"忠孝仁爱、勤耕苦学、克勤克俭。","phone":null,"official":false},{"id":"nanchong-lianzheng-jingshi-guan","name":"南充市廉政警示教育馆","city":"南充市","district":"嘉陵区","address":"南充市纪检监察教育中心内（嘉陵区）","lat":30.7739,"lng":106.0573,"verify":"est","categories":["廉政教育"],"tags":["市级警示教育馆","六大展区","以案明纪","重生之路雕塑"],"year":2022,"summary":"2022 年 7 月 27 日开馆，展陈面积约 1000 平方米。以\"全面从严治党永远在路上\"为主题、\"心\"为题眼设六大展区，文化布展占比约七成，跳出单纯案件震慑的传统模式，是南充市党员干部警示教育的主阵地。","highlights":["\"镌心之痛\"展区专题剖析南充拉票贿选案教训","\"重生之路\"雕塑群中的\"慈母之悲\"最具冲击力","尾厅\"指路明灯\"追问\"入党为什么、当官做什么、身后留什么\""],"story":"展馆最让人驻足的是\"重生之路\"雕塑群——歧路之险、跌倒之痛、慈母之悲、博弈之艰、醒悟之光，完整刻画了一名干部从贪欲初萌到堕落、再到幡然醒悟的轨迹。配合微视频，犯错儿子跪对母亲、母亲含悲呼唤的场景令许多参观者落泪。落马官员的忏悔中几乎都会提到家中望眼欲穿的母亲。展馆以此警示：腐败伤害的不只是个人前程，更是整个家庭。","quote":"心清一切明，心浊一切暗。","phone":null,"official":false},{"id":"guangan-huaying-fenghuo-jidi","name":"红岩·华蓥烽火警示教育基地","city":"广安市","district":"华蓥市","address":"红岩乡高顶村（华蓥山旅游区内）","lat":30.3,"lng":106.81,"verify":"verified","categories":["红色廉洁","廉政教育"],"tags":["第四批省级廉洁文化基地","狱中八条","华蓥山游击队","渝广廉洁教育环线"],"year":2024,"batch":"四川省第四批廉洁文化基地","summary":"2024 年入选第四批四川省廉洁文化基地。基地由红色华蓥纪念墙、红岩·华蓥烽火警示教育基地、华蓥山起义纪念馆及起义遗址群组成，以红岩英烈\"狱中八条\"为核心警示内容。","highlights":["以\"狱中八条\"为警示主线，教育党员干部守住秘密、守住气节","华蓥山起义纪念馆陈列游击队实物与题词","纳入渝广廉洁教育环线跨省联动课程"],"story":"\"华蓥山游击队的革命先辈在面对敌人的威逼利诱时，始终保守党的秘密，与敌人抗争到底。\"这是基地讲解员最常讲的一句话。1948 年前后，华蓥山武装起义失败，大批共产党员被捕牺牲，牺牲者中有的面对酷刑坚贞不屈，有的在生死关头仍严守党的纪律。红岩英烈留下的\"狱中八条\"，第一条就是\"防止领导成员腐化\"，今天被镌刻在警示教育基地中：纪律和忠诚从来不是抽象口号，而是生死关头的选择。","quote":"狱中八条：防止领导成员腐化；加强党内教育和实际斗争的锻炼。","phone":null,"official":true},{"id":"guangan-dangfeng-jiaoyu-zhanting","name":"广安市党风廉政教育展厅","city":"广安市","district":"广安区","address":"广安市党风廉政教育基地综合办公区一楼（广安区）","lat":30.456,"lng":106.633,"verify":"est","categories":["廉政教育"],"tags":["团体预约制","菜单式分层分类","邓小平廉政思想专题展","直播庭审"],"year":2019,"summary":"2019 年 9 月 19 日开馆，位于广安市党风廉政教育基地综合办公区一楼。以\"人生之路 廉洁守护\"为主题，设四个部分及\"邓小平廉政思想与实践\"专题展，实行团体预约制。","highlights":["\"菜单式\"分层分类教育，案例按 19 个类别归集、资源 300 余个","可全程直播职务犯罪庭审现场，\"零距离\"感受纪法威严","尾厅\"初心之印 心手相廉\"打卡与重温入党誓词环节"],"story":"展厅突出\"精准\"二字：根据预约单位的性质和需求匹配教育菜单，讲解员用平板\"一键式\"切换警示内容，把案例按政法系统、医疗系统、国资国企系统等 19 个类别归集。参观者还能实时观看职务犯罪庭审直播、倾听违纪违法人员的\"内心独白\"。尾厅以\"廉\"字墙收束，追问\"我是谁？为了谁？依靠谁？\"让教育有始有终。","quote":"人生之路，廉洁守护。","phone":"0826-2668013","official":false},{"id":"guangan-wusheng-hongse-wenhua-yuan","name":"武胜·红色文化园（初心馆·廉史馆）","city":"广安市","district":"武胜县","address":"飞龙镇白坪村","lat":30.383,"lng":106.326,"verify":"est","categories":["红色廉洁","廉政教育","家风家训"],"tags":["杨益言故居","红岩精神","川渝共建警示教育","廉史馆两条路"],"year":2021,"summary":"占地 100 余亩，2021 年 6 月开园。由\"一场\"（红岩广场）、\"一区\"（思想建设工作展示区）、\"一馆\"（初心馆，含党史馆、廉史馆、先锋馆、同心馆、红岩英雄文化陈列馆）、\"一故居\"（《红岩》作者杨益言故居）组成。","highlights":["廉史馆设\"阳光大道\"与\"歧途\"两条对照展线","\"酒、色、财\"三盏黄灯与监狱、手铐图像形成强烈警示","基层微腐败警示板块由武胜县与重庆合川区共建"],"story":"廉史馆里有两条小道：左侧明亮开阔，是\"阳光大道\"，展示廉政语录与毛熙东、罗纯一等当代先进人物事迹；右侧灰暗压抑，地上划着黄色警戒线，悬着\"酒\"\"色\"\"财\"三个\"黄灯\"，黑色墙体上记录着贪腐官员的教训。这一篇章名叫\"歧途\"，收录的基层微腐败案例由武胜与重庆合川联合提供。一明一暗两条路，几步之间就完成了一次关于人生取舍的思考。","quote":null,"phone":null,"official":false},{"id":"dazhou-wanyuan-baoweizhan","name":"万源保卫战战史陈列馆","city":"达州市","district":"万源市","address":"万源市城区（万源保卫战战史陈列馆）","lat":32.081,"lng":108.036,"verify":"est","categories":["红色廉洁","廉政教育"],"tags":["万源保卫战","川陕苏区","廉动红脉","重温入党誓词"],"year":null,"summary":"陈列川陕苏区万源保卫战相关红色历史文物，是达州市\"清风润心·廉行达州\"廉洁文化地图\"廉动红脉\"主题矩阵的重要点位，常设重温入党誓词等教育环节。","highlights":["以万源保卫战史实展示红军将士的信念与牺牲","设党旗重温入党誓词专区，服务主题党日","与神剑园、红色渠县纪念园串联为红廉线路"],"story":"1934 年，红四方面军在万源与国民党军展开历时数月的大规模防御作战，最终取得胜利，为川陕苏区站稳脚跟奠定基础。战斗中红军将士在极度艰苦的条件下坚守阵地，许多人牺牲时身上只有几发子弹。今天，一批批年轻党员在这座陈列馆里面对党旗重温入党誓词，身后的文物无声诉说着那段烽火岁月。","quote":null,"phone":null,"official":false},{"id":"dazhou-quxian-hongse-jinianyuan","name":"红色渠县纪念园（营渠战役纪念碑·红廉文化长廊）","city":"达州市","district":"渠县","address":"渠县城区（红色渠县纪念园）","lat":30.836,"lng":106.973,"verify":"est","categories":["红色廉洁","廉政教育"],"tags":["营渠战役","红廉文化长廊","红军纪律","烈士陵园"],"year":null,"summary":"占地 120 亩的红色纪念园，为纪念营渠战役及苏区革命活动逐步扩建而成。园内立营渠战役纪念碑、设烈士陵园，并建有红廉文化长廊，是达州廉洁文化地图的重要点位。","highlights":["红廉文化长廊镌刻\"不拿群众一针一线\"\"买卖公平\"等红军纪律","营渠战役纪念碑与烈士陵园构成庄严肃穆的纪念空间","常态化开展廉政课堂与主题党日"],"story":"走进红色渠县纪念园，营渠战役纪念碑巍然矗立，烈士陵园松柏挺拔。最引人注目的是红廉文化长廊，展板上镌刻着红军纪律——\"不拿群众一针一线\"\"买卖公平\"。1933 年营渠战役期间，红军在渠县一带严格执行群众纪律，借物必还、损坏必赔，正是这种秋毫无犯的作风，让川陕苏区在群众中扎下了根。","quote":"不拿群众一针一线，买卖公平。","phone":null,"official":false},{"id":"dazhou-shiqiao-lieningjie","name":"石桥列宁主义街（党性教育现场教学点）","city":"达州市","district":"达川区","address":"石桥镇列宁街中段","lat":31.379,"lng":107.318,"verify":"est","categories":["红色廉洁","家风家训","廉政教育"],"tags":["全国重点文物保护单位","红军石刻标语38幅","忠孝之錾","实景课堂"],"year":null,"summary":"拥有四座清代石牌坊与 38 幅红军石刻标语，为全国重点文物保护单位。中共达川区委党校依托此资源打造立体党性教育现场教学点，展陈馆以\"錾\"为脉络设忠孝之錾、信仰之錾、初心之錾三大展区。","highlights":["\"忠孝之錾\"以四座牌坊讲许、郭、李、汪四姓女子的忠孝勤俭家风","\"信仰之錾\"集中展示 38 幅红军石刻标语","\"初心之錾\"记录烈士易维精事迹与群众世代守护标语往事"],"story":"1933 年红四方面军进驻石桥，在古镇牌坊和墙壁上錾刻下 38 幅石刻标语，把\"不拿群众一针一线\"\"买卖公平\"这样的纪律要求刻进石头，也刻进百姓心里。当地群众顶住压力，一代代守护这些标语直至今日。展陈馆以\"錾\"为脉络：先讲清代牌坊背后忠孝勤俭的传统家风，再讲红军石刻承载的革命主张，最后讲烈士与守护标语的普通人。古牌坊的悠悠古韵与石刻文字的红色初心在此交融。","quote":"不拿群众一针一线。","phone":"0818-7111055","official":false},{"id":"bazhong-jiangshuai-beilin-ji","name":"川陕苏区将帅碑林纪念馆","city":"巴中市","district":"巴州区","address":"红碑路南龛段42号（南龛山）","lat":31.8446,"lng":106.7453,"verify":"est","categories":["红色廉洁","廉政教育"],"tags":["南龛山","碑林长廊","川陕苏区","红色廉政教育"],"year":null,"summary":"与川陕革命根据地博物馆同址，纪念川陕苏区红军将帅。馆区依托南龛山碑林长廊，镌刻红军将士题词与个人单碑，并展示川陕省苏维埃组织法等廉政制度文献，是巴中红色廉政教育的重要阵地。","highlights":["碑林长廊镌刻将帅题词与个人单碑，形成露天红色史书","展示《川陕省苏维埃组织法》与工农监察委员会等制度文献","与川陕革命根据地博物馆一体化开展教育"],"story":"南龛山上，一排排石碑沿山势延伸，镌刻着曾在川陕苏区战斗过的红军将帅题词与姓名。当时的川陕省苏维埃政府颁布组织法，对政权机构设置、干部职责作出严格规定，并设立工农监察委员会。今天，这些制度文献与将帅碑林一起，构成巴中廉洁文化教育中\"制度\"与\"精神\"并重的独特资源——廉洁从来不只是道德自觉，更要靠制度约束。","quote":null,"phone":"0827-2635179","official":false},{"id":"bazhong-yanyangchu-bowuguan","name":"巴中市巴州区晏阳初博物馆","city":"巴中市","district":"巴州区","address":"宕梁街道塔子山一组","lat":31.8687,"lng":106.7719,"verify":"est","categories":["清官廉吏","家风家训","廉政教育"],"tags":["平民教育家","乡村建设","免费开放","知识分子清风"],"year":null,"summary":"位于巴州区塔子山的免费开放博物馆，系统展示平民教育家晏阳初的生平与乡村建设实践，是巴中人文类廉洁教育的重要补充点位，与南龛山将帅碑林、川陕革命根据地博物馆形成城区教育集群。","highlights":["晏阳初放弃优渥条件、终身投身平民教育的清贫选择","\"除天下文盲，做世界新民\"的教育理想与家国情怀","免费开放，面向公众开展人文素养与家风教育"],"story":"晏阳初出生于巴中一个书香家庭，早年留学美国获博士学位。1920 年他放弃海外优越条件回国，立志\"除天下文盲，做世界新民\"，在河北定县等地开展平民教育实验，后又在菲律宾、非洲推广乡村改造。他一生简朴，把募集的经费几乎全部投入教育与乡村建设，自己常年布衣素食，常说知识分子应当\"回到民间去\"。这座博物馆讲的正是这样一种不计名利的清风。","quote":"除天下文盲，做世界新民。","phone":"0827-2266225","official":false},{"id":"bazhong-enyang-wenxintang","name":"恩阳\"问心\"德廉教育基地（问心堂）","city":"巴中市","district":"恩阳区","address":"恩阳古镇（问心堂及红军经理处、县委旧址、革命法庭旧址、川剧魁楼一线）","lat":31.791,"lng":106.635,"verify":"est","categories":["清官廉吏","红色廉洁","廉政教育"],"tags":["喻秉渊挂印守廉","川剧《挂印知县》","一馆一线","问心育廉"],"year":2023,"summary":"恩阳区依托古镇革命旧址群，以\"问心堂\"为主阵地实施\"问心育廉\"工程，整合问心堂、红军经理处、县委旧址、革命法庭旧址、川剧魁楼等资源，打造\"一馆一线\"德廉教育基地。","highlights":["以本土历史廉吏喻秉渊\"挂印守廉\"故事为核心主题","沉浸式体验\"自醒、劝醒、喊醒、警醒\"全过程","创编廉政历史题材川剧《挂印知县》、拍摄纪录片《喻秉渊》"],"story":"喻秉渊是清代恩阳籍官员，在任期间清正自守，因不满官场贪腐，毅然挂印辞官归乡，留下\"挂印守廉\"的佳话。恩阳区纪委监委把这段本土史事作为\"问心堂\"的核心主题，通过图文影像与现场互动，引导参观者沉浸式走完\"自醒、劝醒、喊醒、警醒\"四个环节，还创编川剧《挂印知县》把廉吏故事搬上舞台。一位干部家属参观后说：\"我一定做好监督者，和爱人一起筑好家庭廉洁防线。\"","quote":null,"phone":null,"official":false},{"id":"guangyuan-dashudao-lianjie-jidi","name":"大蜀道廉洁文化基地（展示馆）","city":"广元市","district":"剑阁县","address":"剑门关镇（含翠云廊、剑门关、昭化古城、明月栈道点位）","lat":32.217,"lng":105.575,"verify":"est","categories":["清官廉吏","廉政教育","行业清风"],"tags":["第四批省级廉洁文化基地","点树交印","离任审计","五个一线路"],"year":2024,"batch":"四川省第四批廉洁文化基地","summary":"2024 年入选第四批四川省廉洁文化基地。以展示馆为集中学习阵地，把金牛道上的翠云廊、剑门关、昭化古城、明月栈道串珠成链，设计出\"一馆一廊一关一城一栈道\"的\"五个一\"学习线路。","highlights":["翠云廊\"点树交印\"古制巡演，再现明代知州交接古柏的\"离任审计\"","\"官民相禁剪伐\"\"交树交印\"古柏保护制度及其政绩考核传承","集中呈现金牛道、米仓道、阴平道三条古蜀道上的廉洁文化资源"],"story":"翠云廊上，两位身着明代服饰的\"知州\"一路巡查、清点古柏，最终在剑阁柏前郑重交印——\"点树交印，乃朝廷法度。今存古柏分布如下……\"这场沉浸式巡演，再现了明代以来当地\"官民相禁剪伐\"\"交树交印\"的古柏保护制度，并把保护情况作为政绩考核内容。这种特殊的\"离任审计\"沿袭至今，使翠云廊 1.3 万余株古柏历经千年得以保存。剑阁县纪委监委从中提炼出\"敬畏规则、接续担当\"的政绩观，让古蜀道成为廉洁教育的活课堂。","quote":"点树交印，乃朝廷法度。","phone":"0839-6750978","official":true},{"id":"guangyuan-mingyuexia","name":"明月峡旅游景区（明月栈道）","city":"广元市","district":"朝天区","address":"朝天镇明月村","lat":32.6356,"lng":105.8892,"verify":"verified","categories":["清官廉吏","廉政教育"],"tags":["大蜀道廉洁文化基地点位","中国交通史博物馆","古栈道","清风明月"],"year":null,"summary":"国家 4A 级旅游景区、全国重点文物保护单位，列入大蜀道廉洁文化基地\"五个一\"线路中的\"一栈道\"点位。峡谷集先秦古栈道、嘉陵水道、纤夫鸟道、金牛驿道、108 国道、宝成复线六道于一峡。","highlights":["原名朝天峡，明清取李白\"清风清，明月明\"诗意改名","现存古栈道孔眼 400 余眼，见证历代修治与工程廉洁","被誉\"中国交通史博物馆\"，讲述接续担当"],"story":"明月峡原名朝天峡，明清时期取李白诗中\"清风清、明月明\"之意改名——一个地名，本身就寄托着对清朗政治的期待。峡谷绝壁上的栈道开凿于春秋末年，历经秦汉、三国、两晋、唐宋不断修葺，现存道孔 400 余眼。金牛道上的这些工程，靠的是历代官吏接续组织、百姓前赴后继，任何环节的贪墨懈怠都会让栈道断绝不存。今天它用古道的千年延续讲述责任与担当。","quote":"清风清，明月明。","phone":"0839-8624777","official":false},{"id":"chengdu-lijieren-guju","name":"李劼人故居纪念馆（菱窠）","city":"成都市","district":"锦江区","address":"菱窠西路70号","lat":30.625,"lng":104.115,"verify":"est","categories":["家风家训","红色廉洁"],"tags":["李劼人","菱窠","成都市廉洁文化教育基地","名人故居"],"year":1938,"summary":"成都主城区唯一保存完好并对外开放的近现代名人故居，省级文物保护单位。馆内设故居复原陈列、家风文化展与生平事迹展，是成都市廉洁文化教育基地及示范点。","highlights":["\"独立、进取、厚爱\"六字家训展","《干部登记表》志愿手迹\"愿作一个有益于人民大众的肥料及踏脚石\"","家属遵遗嘱将藏书 28225 册、字画千余件及菱窠全部捐赠国家"],"story":"李劼人是中国现代重要小说家、法国文学翻译家，代表作《死水微澜》《大波》被誉为\"川西民俗的百科全书\"，郭沫若称他为\"中国的左拉\"。他秉持\"独立、进取、厚爱\"的家训，曾任成都市副市长。1962 年逝世后，家属遵其遗嘱将全部藏书、字画连同宅院捐赠国家——一个人的书房变成了所有人的课堂。","quote":"愿作一个有益于人民大众的肥料及踏脚石。","phone":null,"official":false},{"id":"chengdu-dufu-caotang","name":"成都杜甫草堂博物馆","city":"成都市","district":"青羊区","address":"青华路37号","lat":30.662853,"lng":104.026229,"verify":"verified","categories":["清官廉吏","家风家训"],"tags":["四川省廉洁文化基地","杜甫","忧国忧民","诗史堂"],"year":null,"summary":"诗圣杜甫流寓成都时的故居，被誉为\"中国文学史上的圣地\"，四川省廉洁文化基地。馆内保存大廨、诗史堂、工部祠、茅屋等遗迹，以杜甫忧国忧民、推己及人的情操为主线开展廉洁教育。","highlights":["大廨、诗史堂、工部祠与茅屋故居","\"安得广厦千万间\"民本情怀专题","杜甫诗文中的为官之道与家国担当"],"story":"759 年杜甫为避安史之乱入蜀，在浣花溪畔营建茅屋，居住近四年，写下《茅屋为秋风所破歌》等二百余首诗作。屋漏偏逢连夜雨，他想的不是自己，而是\"安得广厦千万间，大庇天下寒士俱欢颜\"。一个连自家屋顶都保不住的老人，替天下寒士惦记了千年——这种\"先人后己\"的排序，正是廉洁最朴素的内核。","quote":"安得广厦千万间，大庇天下寒士俱欢颜。","phone":null,"official":true},{"id":"chengdu-yanhuachi-luyou-ci","name":"崇州罨画池廉洁文化教育专线（陆游祠·琴鹤堂）","city":"成都市","district":"崇州市","address":"崇阳街道大东街54号（罨画池博物馆内）","lat":30.631376,"lng":103.67147,"verify":"verified","categories":["清官廉吏","家风家训"],"tags":["陆游祠","赵抃琴鹤堂","廉洁文化教育专线","川西园林"],"year":null,"summary":"罨画池博物馆内的陆游祠与琴鹤堂，是崇州\"罨画池廉洁文化教育专线\"的核心点位。前者呈现陆游公忠体国的品质，后者复原北宋名臣赵抃\"江原讲学\"场景，讲述其清廉故事。","highlights":["陆游祠·公忠体国主题陈列","琴鹤堂·赵抃\"一琴一鹤\"清白故事","系统梳理典籍、方志、族谱、碑刻千余份，挖掘勤廉典故 70 余个"],"story":"北宋名臣赵抃曾任江原县令，在此开渠引流灌溉农田、劝学兴教，赴蜀任职只携一琴一鹤，人称\"铁面御史\"。相传他见江水清澈，叹道\"吾志如此江清白，虽万类混淆其中，不少浊也\"，清白江由此得名。崇州把陆游祠、琴鹤堂与多处廉洁文化小景串成一条专线，让川西园林里的两位古人隔空对话：一个\"位卑未敢忘忧国\"，一个\"匹马入蜀只携琴鹤\"。","quote":"位卑未敢忘忧国，事定犹须待阖棺。","phone":null,"official":false},{"id":"chengdu-zhanqi-cun","name":"郫都区战旗村廉洁文化基地","city":"成都市","district":"郫都区","address":"唐昌镇战旗村","lat":30.94209,"lng":103.791492,"verify":"verified","categories":["廉政教育","行业清风"],"tags":["战旗村","乡村治理","小微权力清单","三务公开"],"year":null,"summary":"以\"廉洁 + 文旅\"\"廉洁 + 治理\"模式把廉洁文化融入乡村肌理的基层示范点。村内乡村十八坊以豆腐坊\"一清二白\"、布鞋坊\"行必履正\"等匾额喻廉，设廉洁诗词道与廉洁文化长廊。","highlights":["乡村十八坊廉洁匾额：豆腐坊\"一清二白\"、豆瓣坊\"翻晒露\"","\"小微权力清单\"列明 32 项村级事务流程、责任与监督方式","每月 10 日定期公示党务、村务、财务，每周五晚\"清风剧场\"演廉洁小品"],"story":"战旗村把中央八项规定精神翻译成了庄稼人能听懂的话：豆瓣坊的\"翻晒露\"——翻是自查漏洞，晒是村务公开，露是广纳民意；豆腐坊的\"一清二白\"，既是做豆腐的手艺要求，也是做村干部的底线要求。村里还设了\"清风信箱\"和线上举报平台。廉洁在这里不是墙上的标语，而是每个月 10 日贴在公示栏上的几张纸。","quote":"不要人夸颜色好，只留清气满乾坤。","phone":null,"official":false},{"id":"chengdu-qingbaijiang-qingbai-guan","name":"青白江区博物馆 · 清白文化馆","city":"成都市","district":"青白江区","address":"凤凰湖景区旁（青白江区博物馆内）","lat":30.883,"lng":104.241,"verify":"est","categories":["清官廉吏","家风家训"],"tags":["赵抃","铁面御史","清白江地名由来","清白文化"],"year":null,"summary":"设在青白江区博物馆内的常设展馆，以北宋\"铁面御史\"赵抃为主题，通过\"铁面御史\"\"中和治蜀\"\"一生清白\"三个单元，运用文字、图片、雕塑与多媒体展示其清正为官的一生及与清白江的渊源。","highlights":["\"一生清白\"主题展三单元","赵抃\"一琴一鹤\"匹马入蜀故事","清白江（青白江）地名的由来"],"story":"赵抃任殿中侍御史，弹劾不避权贵，人称\"铁面御史\"。他一生\"日所为事，入夜必衣冠露香以告于天\"，赴蜀任职只带一琴一鹤。相传他见江水清澈，说\"吾志如此江清白，虽万类混淆其中，不少浊也\"——一条江因一个人的自许而改名。青白江区把这段渊源做成常设展览：先有清白的志向，才有清白的江水。","quote":"吾志如此江清白，虽万类混淆其中，不少浊也。","phone":null,"official":false},{"id":"panzhihua-kaifa-jianshe-ji","name":"攀枝花开发建设纪念馆","city":"攀枝花市","district":"东区","address":"大渡口南街12号","lat":26.5536,"lng":101.6982,"verify":"verified","categories":["红色廉洁","行业清风"],"tags":["三线建设","渡口记忆","干打垒","现场教学点"],"year":null,"summary":"攀枝花中国三线建设博物馆分馆之一，以攀枝花（原渡口）开发建设初期的办公、生活场景复原和历史实物为主，再现 1965 年前后\"备战备荒为人民\"的创业现场，是干部培训现场教学点。","highlights":["还原开发建设初期简陋办公与生活场景","第一代建设者\"干打垒\"精神实物展陈","与三线建设博物馆、大田会议纪念馆构成参观闭环"],"story":"攀枝花因三线建设而生。当年建设者从全国各地汇聚到这片荒山，住席棚子、点煤油灯，却把国家重点项目一项项干成。纪念馆保存的桌椅、图纸、文件与生活用具，让参观者直观感到\"条件越苦、纪律越严\"——不是苦日子值得怀念，而是那种在苦日子里不伸手的自觉值得记住。","quote":null,"phone":null,"official":false},{"id":"panzhihua-datian-huiyi-ji","name":"大田会议纪念馆","city":"攀枝花市","district":"仁和区","address":"大田镇大田新街7号","lat":26.3161,"lng":101.7766,"verify":"verified","categories":["红色廉洁","廉政教育"],"tags":["大田会议","建市决策","调查研究","民主集中"],"year":null,"summary":"攀枝花中国三线建设博物馆分馆之一。1965 年在此召开的大田会议确定了攀枝花工业区总体规划与厂址布局，被视为攀枝花建市的决策起点。馆内以会议场景复原和史料陈列，讲述重大决策如何坚持科学论证与民主集中。","highlights":["重大工程决策中的调查研究与集体决策传统","攀枝花工业区总体规划形成过程史料","与三线建设博物馆联动开展\"决策与担当\"主题教学"],"story":"1965 年，中央在大田召开会议，就攀枝花的厂址、布局反复比较论证，最终确立\"弄弄坪\"等方案。会议坚持先调查后决策、先论证后拍板，避免了盲目上马带来的巨大损失。这段历史提示今天的党员干部：任何个人专断和拍脑袋决策，都可能造成难以挽回的浪费。","quote":null,"phone":null,"official":false},{"id":"panzhihua-huohong-nianhua","name":"火红年华三线建设主题廉洁教育基地","city":"攀枝花市","district":"西区","address":"河门口街道高家坪社区（原渡口水泥厂《火红年华》拍摄基地）","lat":26.5988,"lng":101.5896,"verify":"verified","categories":["红色廉洁","廉政教育"],"tags":["沉浸式教学","干打垒","创业饭","全国劳模访谈"],"year":2022,"summary":"依托电视剧《火红年华》高家坪拍摄基地复原三线建设场景建设的沉浸式主题教育基地，设初心园、影视基地、微景观等展区，开展参观、访谈全国劳模、共做\"创业饭\"等体验课程。","highlights":["劈柴架锅做\"创业饭\"，重现\"三块石头架口锅\"的艰苦场景","走访全国劳模、聆听三线建设者先进事迹","三线建设干部学院西区分院现场教学点，可承接主题党日"],"story":"高家坪原是渡口水泥厂的生活区，红砖房、搪瓷杯、旧报纸还原了当年建设者的日常。学员在这里重走背水小道、体验干打垒建房，再吃一顿自己动手做的\"创业饭\"，从体力付出中体会父辈的艰辛。教育基地走的是\"体验—共情—反思\"的路径，把艰苦奋斗、群众观念和廉洁自律教育揉进了一顿饭里。","quote":"三块石头架口锅。","phone":null,"official":false},{"id":"panzhihua-panggang-qinzheng","name":"攀钢轨梁厂勤政树廉馆","city":"攀枝花市","district":"东区","address":"弄弄坪（攀钢集团攀枝花钢钒有限公司轨梁厂）","lat":26.5665,"lng":101.692,"verify":"verified","categories":["行业清风","廉政教育"],"tags":["国企廉洁","百米钢轨","千锤百炼","岗位廉洁风险"],"year":null,"summary":"依托拥有世界一流万能轧机七机架布置工艺的攀钢轨梁厂万能生产线建设的廉洁教育阵地，厂区\"勤政树廉馆\"把钢铁生产的\"千锤百炼\"与企业廉洁从业教育相结合，是干部培训现场教学点。","highlights":["从钢轨\"高强韧性、高纯净度\"工艺比喻干部队伍纯洁性","\"勤政树廉馆\"展示国企党风廉政建设与廉洁风险防控做法","近距离观摩百米钢轨轧制全过程，感受产业工人的严谨作风"],"story":"一根百米钢轨要经过反复加热、轧制、矫直、检测，任何一道工序偷工减料都会留下隐患。轨梁厂把这种\"千锤百炼方成钢\"的工业逻辑引入廉洁教育：党性修养同样需要反复锤炼、时时校准。\"勤政树廉馆\"用身边案例讲清岗位廉洁风险点，提醒干部职工守住底线、勤勉履职——钢轨的纯净度靠工艺，干部的纯净度靠自律。","quote":"千锤百炼方成钢。","phone":null,"official":false},{"id":"panzhihua-juqueyan-bwg","name":"中国苴却砚博物馆","city":"攀枝花市","district":"仁和区","address":"仁和镇（渡仁西线路歇桥南侧、大河景观旁）","lat":26.5016,"lng":101.7369,"verify":"est","categories":["家风家训","清官廉吏"],"tags":["苴却砚","中国彩砚","以砚喻廉","存墨不腐"],"year":2015,"summary":"国内第一个以砚为主题的博物馆，2015 年建成投用，建筑面积约 4482 平方米，设 6 个展厅，藏苴却石艺术品、苴却砚、根雕、书画等 1886 件。以\"砚\"为载体开展廉洁文化教育。","highlights":["\"存墨不腐，留有余香\"——以砚台品格喻为官操守","苴却砚集端砚之\"眼\"、歙砚之\"膘\"、洮砚之\"色\"、澄泥砚之\"质\"","文房清供文化中的家风家训与清官廉吏故事"],"story":"苴却砚因金沙江沿岸古称\"苴却\"而得名，石质坚硬细腻、莹洁滋润，砚堂呵气凝珠，寒冬不冰、盛夏存墨不腐。古人以砚为友，取\"石可破而不可夺其坚\"之意。博物馆借砚说廉：一方好砚贵在本色不改、存墨不腐；一名干部贵在初心不变、清廉自守。","quote":"存墨不腐，留有余香。","phone":null,"official":false},{"id":"liangshan-huili-hongjun-ji","name":"红军长征过会理纪念馆","city":"凉山彝族自治州","district":"会理市","address":"环城西路中段2号","lat":26.6545,"lng":102.242,"verify":"est","categories":["红色廉洁","廉政教育"],"tags":["凉山州廉政教育基地","巧渡金沙江","全国爱国主义教育示范基地","六个篇章"],"year":null,"summary":"含红军长征过会理纪念馆、巧渡金沙江陈列馆、会理会议陈列馆，以六个篇章介绍中央红军长征重大历史事件及在会理期间的活动，设\"爱国主义、廉政教育\"专项社教板块。","highlights":["设\"爱国主义、廉政教育\"专门社教栏目，常态化承接党纪学习教育","以重温入党誓词、讲解红色历史、讲述廉洁故事\"三合一\"组织教育","2024 年 5—7 月单季接待 148 个党组织、4038 名党员干部"],"story":"1935 年 5 月，中央红军巧渡金沙江进入会理。纪念馆用图文展板、场景复原和实物文物，把长征途中纪律如铁、依靠群众的细节一一呈现：借住民房打扫干净再走，取用粮食留下凭据。会理市把这里作为廉政教育基地，引导党员干部从长征故事里读出\"守纪律、讲规矩\"的当代分量。","quote":null,"phone":null,"official":false},{"id":"liangshan-xichang-jiafeng-guan","name":"西昌家风馆","city":"凉山彝族自治州","district":"西昌市","address":"邛海湿地六期内","lat":27.82,"lng":102.29,"verify":"est","categories":["家风家训","廉政教育"],"tags":["先贤家风","邛都家风","红色家风","时代新风"],"year":null,"summary":"位于邛海湿地六期内，室内建筑面积 1100 平方米。以\"先贤家风\"\"邛都家风\"\"红色家风\"\"时代新风\"四个板块为核心，围绕\"家和万事兴\"主题，以家训、家书为载体展示传统家训、红色家风及当代文明家庭故事。","highlights":["四大板块串联本土家风与红色家风","与驻地单位共建\"廉洁文化教育基地\"","周二至周日免费开放，周一闭馆"],"story":"家风连着党风政风。西昌家风馆把本土历史中的优秀家风与老一辈革命家的红色家风并置展出，用一封封家书、一条条家训说明\"家风正则作风正\"。许多单位组织党员干部带着家属前来参观，在\"家是最小国\"的叙事中，引导干部把好家庭关、亲情关。","quote":"家和万事兴。","phone":"0834-3222872","official":false},{"id":"liangshan-fulian-jiajiao-jiafeng-guan","name":"凉山州妇联家教家风主题展览馆","city":"凉山彝族自治州","district":"西昌市","address":"中所安置新村（建昌东路246号）","lat":27.895,"lng":102.27,"verify":"est","categories":["家风家训","廉政教育"],"tags":["家教家风","树新风促振兴","家和万事兴","团体预约"],"year":2022,"summary":"2022 年 6 月 8 日对外开放，服务\"树新风 促振兴\"暨妇女儿童关爱提升三年行动。围绕\"家和万事兴\"主题，以家训、家书为载体分三个部分展示中国传统家训、红色家风及当代文明家庭故事。","highlights":["配有专业讲解、情景剧目表演、现场有奖问答等互动服务","周一至周五免费开放，主要接受单位、组织、团队预约参观","展陈内容经中央党史和文献研究部门审核把关"],"story":"展览馆用\"家训、家书\"两条线索，把中华传统家训、革命先辈红色家风与身边的文明家庭故事连成一气。参观者既是观众也是讲述人——不少单位在参观后组织干部写家书、立家规。把廉洁教育从单位课堂延伸到家庭日常，这或许是最难也最有效的一步。","quote":"家和万事兴。","phone":null,"official":false},{"id":"liangshan-ningnan-gantang-yiai","name":"宁南县\"甘棠遗爱\"廉政主题公园","city":"凉山彝族自治州","district":"宁南县","address":"幸福镇（幸福茶岭森林康养景区内）","lat":27.1,"lng":102.78,"verify":"est","categories":["廉政教育","清官廉吏"],"tags":["甘棠遗爱","茶文化","核桃文化","幸福大讲堂"],"year":2023,"summary":"宁南县幸福镇在\"清廉凉山\"建设中把廉洁元素植入人文景观与自然风貌，建成\"甘棠遗爱\"廉洁主题公园、\"清廉飘香\"茶文化长廊、\"干净内核\"核桃文化阵地等 5 处宣教点位，并设计 3 个廉政卡通形象。","highlights":["\"甘棠遗爱\"古树主题公园，取召公听政甘棠之下、遗爱在民的典故","园内\"幸福大讲堂\"由镇班子成员带头上党课，推出\"清廉套餐\"","以\"茶清清白白\"\"核桃干净内核\"就地取材讲廉洁"],"story":"幸福镇有万余亩生态茶园、20 万余亩核桃和千年古黄桷树。当地干部说：茶，清清白白；核桃，干净内核；树，遗爱百姓——这些寓意与廉洁文化高度契合。于是镇里把廉洁元素植入景区，把古树命名为\"甘棠遗爱\"，让群众和干部在日常休闲中接受熏陶，实现\"寓教于情、寓教于乐\"。","quote":"甘棠遗爱。","phone":null,"official":false},{"id":"aba-maerkang-dangfeng-lianjie","name":"马尔康党风廉洁教育基地（卓克基红军长征纪念馆内）","city":"阿坝藏族羌族自治州","district":"马尔康市","address":"卓克基镇卓克基红军长征纪念馆内","lat":31.8689,"lng":102.2907,"verify":"verified","categories":["廉政教育","红色廉洁"],"tags":["廉洁门","警示教育厅","为官十慎","优良家风家训"],"year":null,"summary":"建筑面积 430 余平方米，以\"坚定走好新时代全面从严治党长征路\"为主题，由序厅、工作纪实厅、警示教育厅、梦想使命厅组成，设\"警示、警心、警醒\"三大板块，是阿坝州党纪学习教育现场教学点。","highlights":["\"廉洁门\"刻孟浩然\"看取莲花净，应知不染心\"与周敦颐《爱莲说》","\"利剑高悬、腐心勿动\"装置艺术，警示腐心一动必被铁拳砸入深渊","\"为官十慎\"与电子签名廉洁承诺互动环节"],"story":"基地把红色廉政基因与新时代全面从严治党要求接续呈现：工作纪实厅讲\"纪律如钢、作风如铁、执纪如山\"的传统，警示教育厅用阿坝州查处的身边案例教育身边人，梦想使命厅以藏羌回汉楷模和\"为官十慎\"引导见贤思齐。参观结束时，参观者可在电子屏留下自己的廉洁承诺——把话说出口，也是一种自我约束。","quote":"出淤泥而不染，濯清涟而不妖。","phone":"0837-2829316","official":false},{"id":"aba-xiaojin-lianghe-lianjie","name":"小金县两河廉洁文化教育基地","city":"阿坝藏族羌族自治州","district":"小金县","address":"两河口镇红军长征两河口会议纪念馆内（另设梦笔山\"雪山红路\"、县城法治文化广场两块）","lat":31.4899,"lng":102.4889,"verify":"verified","categories":["红色廉洁","廉政教育"],"tags":["两河口会议","王瑛","雪山红路","算好三本账"],"year":2012,"summary":"分设于红军长征两河口会议纪念馆、梦笔山\"雪山红路\"和县城法治文化广场三处。馆内廉洁教育馆 2012 年 5 月建成，展馆 230 余平方米，以四大篇章把红色文化与廉政文化有机融合。","highlights":["追忆出生于小金两河 802 林场的全国纪检监察干部楷模王瑛同志事迹","5 个警钟与大算盘，寓意\"算好政治账、家庭账、经济账，把好五道关\"","\"雪山红路\"实景体验翻越梦笔山，感悟艰苦奋斗"],"story":"小金是纪检战线楷模王瑛的出生地，她出生在小金县两河 802 林场，成长于梦笔雪山脚下，2018 年被授予\"改革先锋\"称号。廉洁教育馆用一颗红心环绕的照片墙讲述她忠诚履职的一生；展厅尽头的算盘与警钟提醒每一位参观者：为官从政要常算\"三本账\"、严守\"五道关\"，让警钟长鸣、让清风常在。","quote":"算好三本账，把好五道关。","phone":"0837-2799921","official":false},{"id":"aba-wenchuan-yingxiu-zhenzhong","name":"汶川映秀震中纪念馆","city":"阿坝藏族羌族自治州","district":"汶川县","address":"映秀镇（漩口中学遗址、家国情怀宣誓广场旁）","lat":31.0565,"lng":103.4863,"verify":"verified","categories":["廉政教育","家风家训"],"tags":["廉洁救灾","阳光重建","家国情怀","特殊党费"],"year":null,"summary":"汶川县深入挖掘抗震救灾、恢复重建过程中廉洁内涵打造的廉洁文化阵地，含漩口中学遗址、家国情怀宣誓广场、映秀震中纪念馆、大爱磐石广场、七一映秀中学等点位。","highlights":["廉政走廊以 2800 多个项目、750 多亿元资金的台账与工作笔记，讲述\"廉洁救灾，阳光重建\"","家国情怀宣誓广场\"母亲·初心\"主雕塑与\"四梁八柱\"浮雕","七一映秀中学由中组部\"特殊党费\"4654 万元全额援建"],"story":"\"5·12\"特大地震后，灾后重建资金量巨大、项目众多。阿坝州纪检监察系统进驻一线，逐项建立台账、逐笔核对资金，把\"廉洁救灾，阳光重建\"落到每一本工作笔记上。展馆里那一摞摞台账，既是对灾区人民的交代，也是对全体党员干部的示范：越是急难险重，越要把纪律和规矩挺在前面。","quote":"廉洁救灾，阳光重建。","phone":"0837-6225480","official":false},{"id":"aba-heishui-changde","name":"黑水县廉洁文化教育基地（红色昌德）","city":"阿坝藏族羌族自治州","district":"黑水县","address":"沙石多镇昌德村","lat":32.1044,"lng":102.8102,"verify":"est","categories":["红色廉洁","廉政教育"],"tags":["筹粮熬盐","买卖公平","长征干部学院教学点","红色微党课"],"year":null,"summary":"位于黑水县沙石多镇昌德村，是长征干部学院重要教学基地之一。以红军长征翻越昌德雪山的红色底蕴为基础，建设红军文化广场、观景平台等，设沙盘模拟、红色微党课、体验式教学四个环节。","highlights":["微党课《忆筹粮熬盐 叙鱼水深情》讲述\"所筹之粮按价付银元布匹、未付者均打借条\"","昌德雪山主题雕塑再现藏族同胞送粮送盐支援红军场景","体验式教学含炒磨青稞、拾柴禾、采野菜、割青稞"],"story":"红军近 9 万人三进三出黑水，历时一年零两个月，行程 1500 多公里。为解决给养，红军开展大规模熬盐筹粮：共筹集粮食 710 万斤、熬制食盐 5000 余斤，借用宰食牲畜 3 万余头。所筹之粮有的按当地粮价付了银元和布匹，没付钱的也都留下借条。正是这种秋毫无犯、买卖公平的纪律，让藏族群众把红军当成亲人。","quote":null,"phone":"0837-6722199","official":false},{"id":"aba-jinchuan-hongjun-laojie","name":"金川红军老街城","city":"阿坝藏族羌族自治州","district":"金川县","address":"勒乌镇老街（红军革命纪念建筑群）","lat":31.4775,"lng":102.0632,"verify":"verified","categories":["红色廉洁","廉政教育"],"tags":["省级革命文物保护单位","格勒得沙","民族区域自治实践","徐向前指挥部旧址"],"year":null,"summary":"老街古称阿尔古，有 200 多年历史，是阿坝州境内规模最大、种类最多、最为集中的红军革命纪念建筑群，2007 年被评为省级革命文物保护单位。1935 年 6 月至 1936 年 7 月红军在金川历时 14 个月。","highlights":["格勒得沙共和国中央革命政府旧址，讲述党的民族政策早期探索","徐向前指挥部旧址、红四方面军总医院、炸弹炸药厂、被服厂旧址群","红军军械修理厂旧址（原城隍庙），格勒得沙共和国成立大会召开地"],"story":"1935 年红军占领绥靖后，针对少数民族聚居的实际，大力培训少数民族积极分子，1935 年 11 月 28 日在绥靖城隍庙群众大会上宣告成立格勒得沙共和国，制定国界、国歌，组建格勒得沙革命军。这是党的民族区域自治政策的一次宝贵探索。旧址群提醒后人：尊重实际、依靠群众、依法建制，是党的事业不断胜利的重要经验。","quote":null,"phone":"0837-2522258","official":false},{"id":"ganzi-ludingqiao-ji","name":"红军飞夺泸定桥纪念馆","city":"甘孜藏族自治州","district":"泸定县","address":"泸桥镇丰碑街2号","lat":29.9145,"lng":102.2302,"verify":"verified","categories":["红色廉洁","廉政教育"],"tags":["飞夺泸定桥","文物考古研究所","现场教学","红色研学"],"year":null,"summary":"与泸定县文物考古研究所合署，与红军飞夺泸定桥纪念碑公园、泸定桥共同构成核心红色教育片区。馆内以实物、场景与图片系统展示 1935 年 5 月 29 日飞夺泸定桥的战斗经过。","highlights":["完整呈现飞夺泸定桥战斗经过与 22 名勇士事迹","与纪念碑公园、泸定桥景区连片，可一站完成红色廉洁教育","陈列红军将士缝满补丁的衣服、穿到断裂的草鞋"],"story":"1935 年 5 月，红军一昼夜奔袭 240 里赶到泸定桥，22 名突击队员攀着铁索冲过火墙。纪念馆里陈列着红军将士缝满补丁的衣服、穿到断裂的草鞋。今天人们在这里重温这段历史，读出的不只是英勇，更是\"令行禁止、一往无前\"的组织纪律——这是红军能够战胜强敌的根本原因之一。","quote":"大渡桥横铁索寒。","phone":"0836-3122117","official":false},{"id":"ganzi-xueyu-qingfeng-guan","name":"甘孜州廉洁文化教育基地\"雪域清风馆\"","city":"甘孜藏族自治州","district":"泸定县","address":"泸桥镇下田村","lat":29.905,"lng":102.233,"verify":"est","categories":["廉政教育","红色廉洁"],"tags":["州纪委监委直管","警示教育","纪律教育","预约参观"],"year":2026,"summary":"甘孜州纪委监委打造的廉洁文化教育基地，以\"雪域清风·廉洁甘孜\"为主题，以纪律主线串联序厅及\"映雪篇·稳藏安康 挺膺担当\"\"澄域篇·铸牢忠诚 固稳大局\"\"扬清篇·铁腕反腐 震慑常在\"三个主展厅。","highlights":["面向州内党政机关、事业单位、国企、村（社区）党组织和党校主体班集体开放","单批次控制在 30—50 人，每批时长 50—80 分钟","须统一组织、提前 3 个工作日提交加盖公章的预约申请表，展厅内禁止录音录像"],"story":"雪域清风馆是全州党员干部拒腐防变的\"实景课堂\"。三个主展厅从\"稳藏安康、挺膺担当\"的政治责任，到\"铸牢忠诚、固稳大局\"的纪律要求，再到\"铁腕反腐、震慑常在\"的警示震慑，层层递进。参观过程中不得携带手机和具有录音录像功能的智能穿戴设备——这种严格本身，就是一次纪律教育。","quote":"雪域清风·廉洁甘孜。","phone":"0836-2833968","official":false},{"id":"ganzi-moxi-huiyi-jiuzhi","name":"磨西会议旧址（毛泽东住地旧址）","city":"甘孜藏族自治州","district":"泸定县","address":"磨西镇磨西天主教堂神甫楼（磨西古镇内）","lat":29.6474,"lng":102.1213,"verify":"verified","categories":["红色廉洁","廉政教育"],"tags":["磨西会议","红军长征纪念馆","爱国主义教育基地","灾后重建"],"year":null,"summary":"1935 年 5 月 29 日晚，连续行军三天的毛泽东率队到达磨西，夜宿磨西天主教堂神甫楼，并连夜召开会议部署飞夺泸定桥的具体计划，史称\"磨西会议\"。现为著名爱国主义教育基地。","highlights":["纪念馆末单元展示\"9·5\"泸定地震后各族人民团结一心抗震救灾场景","毛泽东住地旧址与磨西老街按\"修旧如旧\"原则抢救性保护","海螺沟景区管委会推出小志愿者义务讲解活动"],"story":"磨西是红军长征进入甘孜藏区的第一镇。1935 年 5 月的那一夜，中央领导在神甫楼里紧急磋商，第二天飞夺泸定桥的命令由此发出。2022 年\"9·5\"泸定地震后，当地按抢救性保护原则全力抢修旧址，做到修旧如旧。干部们说，把灾后重建干好、把群众日子带好，就是对长征精神最好的传承。","quote":null,"phone":null,"official":false},{"id":"ganzi-zhude-geda-ji","name":"朱德总司令和五世格达活佛纪念馆","city":"甘孜藏族自治州","district":"甘孜县","address":"甘孜镇旭日林民族风情村内","lat":31.6274,"lng":99.9887,"verify":"est","categories":["红色廉洁","廉政教育"],"tags":["民族团结","博巴政府","红军长征","全国重点文物保护单位"],"year":1993,"summary":"1991 年经中共中央办公厅批准建设、1993 年竣工，占地 14000 平方米、展馆 900 平方米，2013 年改扩建。馆内陈列五世格达活佛生平、红军长征途经甘孜的事迹与革命文物 100 余件。","highlights":["朱德总司令会见五世格达活佛塑像，讲述红军与藏族宗教界人士的团结合作","博巴政府（第一个民族地区苏维埃政权）史料，展现党的民族政策早期实践","红军长征路线图、红四方面军路线图等文物 100 余件"],"story":"1936 年，红四方面军到达甘孜，五世格达活佛积极支援红军，动员群众为红军筹集粮食、救护伤病员。朱德总司令与格达活佛结下深厚情谊，红军北上后活佛仍想方设法保护留下的伤病员。这段藏汉团结的佳话说明：党的民族政策和群众纪律，是赢得各族群众真心拥护的根本。","quote":null,"phone":null,"official":false},{"id":"ganzi-lengqi-lianzheng-guangchang","name":"冷碛镇廉政文化广场","city":"甘孜藏族自治州","district":"泸定县","address":"冷碛镇","lat":29.789,"lng":102.226,"verify":"verified","categories":["廉政教育","家风家训"],"tags":["廉洁教育路线","基层廉洁文化","茶马古道","群众身边"],"year":null,"summary":"泸定县廉洁教育路线的组成部分。泸定县纪委监委以红军飞夺泸定桥纪念碑公园为主体，整合全县蕴含廉洁元素的红色基地、历史古迹、文化展馆、村居村落资源，精心开发为一条廉洁教育路线。","highlights":["面向基层群众开放，是廉洁文化进乡镇、进村居的示范点","与兴隆镇茶马古道、岚安乡烈士陵园串联成线","配合\"泸小廉\"廉洁文化 IP 开展线下宣传"],"story":"廉洁文化建设不能只在机关大院里做文章。泸定县把廉政文化广场建在镇上，让赶集的群众、放学的孩子都能看见廉洁故事、记住廉洁警句。冷碛镇自古是茶马古道上的重镇，商旅往来讲究\"一诺千金\"。当地人把这份诚信传统与今天的廉洁要求对接，让清风正气在群众身边落地生根。","quote":null,"phone":null,"official":false}];
